W.UNIT.push({"id": "L22", "title": "L22 Skin and Subcutaneous Tissue", "short": "L22", "src": "__L22_Skin_and_Subcutaneous_Tissue__jodx78_.pdf (73 หน้า สไลด์ + ไฮไลต์ + ลายมือ)", "topic": "Plastic & Reconstructive surgery", "tags": ["Plastic"], "QB": [{"n": 1, "notes": "p2 รูป: <b>Epidermis · Papillary dermis · Reticular dermis · Subcutaneous fat · Sweat gland and duct · Sebaceous gland · Hair follicle · Cutaneous nerve</b>", "stem": "A 30-year-old man has a full-thickness skin graft harvested from the groin. Which structures are found in the dermis of the harvested skin?", "opts": ["Lymph nodes and bone marrow", "Subcutaneous fat lobules only", "Only keratinocytes and melanocytes", "Hair follicles, sebaceous glands and sweat glands", "Skeletal muscle fibers and tendons"], "ans": 3, "interp": "", "why": "p2: structure of normal skin — epidermis, papillary/reticular dermis มี hair follicle, sebaceous gland, sweat gland and duct, cutaneous nerve · subcutaneous fat อยู่ใต้ dermis", "wrong": {"A": "ไม่ใช่", "B": "อยู่ชั้นใต้ dermis", "C": "นั่นคือ epidermis", "E": "ไม่ใช่ผิวหนัง"}, "summary": ["Dermis มี skin appendages + vessels + nerves"], "kimg": ["l22_p2"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 2 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 2, "notes": "p2 ลายมือ: <b>“form plexus at dermo-epidermo j<sup>n</sup>” · “วิ่งเหนือ fascia แทงขึ้น (perforator)”</b>", "stem": "A 45-year-old woman has necrosis of the skin overlying a deep infection that has destroyed vessels running above the fascia. Which anatomical arrangement explains why the overlying skin died?", "opts": ["Each layer of the skin is supplied by a separate artery arising from the bone beneath it", "Skin is supplied only by lymphatics", "Skin receives its blood supply directly from vessels running inside the epidermis itself, which has its own capillaries", "Each hair follicle has its own artery from the muscle", "Skin is supplied by perforators that pass up from vessels running above the fascia to form dermal plexuses"], "ans": 4, "interp": "", "why": "ลายมือ p2: เส้นเลือด form plexus at dermo-epidermal junction · วิ่งเหนือ fascia แทงขึ้น (perforator) → ถ้าชั้นเหนือ fascia พัง ผิวด้านบนขาดเลือด (เหมือน necrotizing fasciitis p69)", "wrong": {"A": "มี plexus", "B": "ไม่ใช่", "C": "epidermis ไม่มีหลอดเลือด", "D": "ไม่ใช่"}, "summary": ["Perforator → dermal plexus"], "kimg": ["l22_p2"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 2 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 3, "notes": "p4: <b>Benign papilloma — An overgrowth of all layers of the skin with a central vascular core</b> · ลายมือ: <span class=\"hw\">= ติ่งเนื้อ (skin tag) → not required tx</span>", "stem": "A 50-year-old woman has a soft, skin-colored lesion hanging on a narrow stalk in her axilla. Histology shows all skin layers around a central vascular core. What is the most appropriate statement?", "opts": ["It is a benign papilloma that does not require treatment unless bothersome", "It is a premalignant lesion that requires wide excision with a 1-cm margin of normal skin", "It must be treated with radiotherapy", "It is a sebaceous cyst", "It is a basal cell carcinoma"], "ans": 0, "interp": "", "why": "p4: benign papilloma = an overgrowth of all layers of the skin with a central vascular core (ลายมือ = ติ่งเนื้อ (skin tag) → not required tx)", "wrong": {"B": "benign", "C": "ไม่ใช่", "D": "ไม่มี core เป็นถุง", "E": "ไม่ใช่"}, "summary": ["Skin tag: all layers + vascular core → ไม่ต้องรักษา"], "kimg": ["l22_p4", "l22_p5"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 4, 5 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 4, "notes": "p5: <b>A papilloma — Narrow pedicle, almost a fibrolipomatous polyp · occur anywhere on the skin · shape and size: variable</b> · ลายมือ: <span class=\"hw\">ที่ใหญ่ → excision · ถ้าที่เล็ก = จี้ออก / กรรไกรตัด</span>", "stem": "A 40-year-old man asks to have a 2-mm skin tag on his neck removed for cosmetic reasons. Which method is appropriate?", "opts": ["Radiotherapy", "Mohs micrographic surgery", "Snip excision with scissors or cautery", "Sentinel lymph node biopsy", "Wide excision with 1-cm margins"], "ans": 2, "interp": "", "why": "ลายมือ p5: ถ้าใหญ่ → excision · ถ้าเล็ก = จี้ออก / กรรไกรตัด · narrow pedicle", "wrong": {"A": "ไม่ใช่", "B": "ไม่จำเป็น", "D": "ไม่ใช่", "E": "benign"}, "summary": ["Skin tag เล็ก → จี้/ตัดด้วยกรรไกร"], "kimg": ["l22_p4", "l22_p5"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 4, 5 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 5, "notes": "p6: <b>Seborrhoeic keratosis — The plaque consists of an excess number of basal cell and will peel off</b> · ลายมือ: <span class=\"hw\">= พบคนแก่ → เยอะขึ้นตามวัย / family history · เอานิ้วแกะก็หลุด → ขึ้นใหม่</span>", "stem": "A 72-year-old man has several brown, 'stuck-on', greasy plaques on his back that partly peel off when scratched, then recur. His father had similar lesions. What is the diagnosis?", "opts": ["Actinic keratosis", "Superficial basal cell carcinoma", "Seborrheic keratosis", "Malignant melanoma", "Bowen's disease"], "ans": 2, "interp": "", "why": "p6: seborrhoeic keratosis (ลายมือ = พบคนแก่ → เยอะขึ้นตามวัย / family history) · plaque of excess basal cells that will peel off (เอานิ้วแกะก็หลุด → ขึ้นใหม่)", "wrong": {"A": "ปื้นแดงสาก ที่ถูกแดด", "B": "ไม่หลุดเมื่อแกะ", "D": "ต้องมีลักษณะ ABCD", "E": "ปื้นแดงขุย"}, "summary": ["SK: คนแก่ stuck-on แกะหลุด benign"], "kimg": ["l22_p6"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 6 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 6, "notes": "p6 ลายมือ: <b>“Tx = จี้ออก (cosmetic)”</b> · p23 ลายมือ: <b>“cf. seborrheic keratosis → benign”</b>", "stem": "A 68-year-old woman with a typical seborrheic keratosis on her cheek asks whether it will become cancer and how it is treated. What is the best answer?", "opts": ["It requires topical chemotherapy", "It is benign; removal by curettage or cautery is cosmetic", "It is premalignant and needs excision with margins", "It must be biopsied every year", "It becomes squamous cell carcinoma in most cases and must be widely excised"], "ans": 1, "interp": "", "why": "ลายมือ p6: Tx = จี้ออก (cosmetic) · p23 ลายมือ: cf. seborrheic keratosis → benign", "wrong": {"A": "ไม่จำเป็น", "C": "ไม่ใช่ premalignant", "D": "ไม่จำเป็น", "E": "= actinic keratosis"}, "summary": ["SK = benign → cosmetic removal"], "kimg": ["l22_p6"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 6 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 7, "notes": "p7: <b>Keratoacanthoma</b> · ลายมือ: <b>“มี keratin อุดอยู่ · ปล่องภูเขาไฟ = ก้อนที่ตรงกลางบุ๋ม · ถ้าก้อนใหญ่ : อาจสับสนกับ squamous cell carcinoma (ลอง bx ไปตรวจ)”</b>", "stem": "A 70-year-old man has a rapidly growing, dome-shaped nodule on his cheek with a central crater filled with keratin. What is the most appropriate next step?", "opts": ["Reassure without follow-up", "Biopsy or excision because it can mimic squamous cell carcinoma", "Cryotherapy without histology", "Wide excision with 2-cm margins and sentinel lymph node biopsy straight away", "Topical steroid"], "ans": 1, "interp": "", "why": "ลายมือ p7: keratoacanthoma — มี keratin อุดอยู่ · ปล่องภูเขาไฟ = ก้อนที่ตรงกลางบุ๋ม · ถ้าก้อนใหญ่ อาจสับสนกับ SCC (ลอง bx ไปตรวจ)", "wrong": {"A": "ต้องแยก SCC", "C": "ไม่มีชิ้นเนื้อ", "D": "เกินจำเป็น", "E": "ไม่ใช่"}, "summary": ["KA ปล่องภูเขาไฟ → bx/excision (แยก SCC)"], "kimg": ["l22_p7"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 7 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "img": ["l22_p7"]}, {"n": 8, "notes": "p7 ลายมือ: <b>“ถ้าก้อนใหญ่ : อาจสับสนกับ squamous cell carcinoma”</b>", "stem": "A 65-year-old farmer has a 1.5-cm nodule on the nose that appeared over 6 weeks. It has rolled edges and a central keratin-filled crater. Which lesion is the main differential diagnosis?", "opts": ["Lipoma", "Capillary malformation", "Sebaceous cyst", "Skin tag", "Squamous cell carcinoma"], "ans": 4, "interp": "", "why": "ลายมือ p7: keratoacanthoma ถ้าก้อนใหญ่ อาจสับสนกับ squamous cell carcinoma", "wrong": {"A": "นุ่ม ใต้ผิว", "B": "ไม่ใช่ก้อน keratin", "C": "ติดผิว มี punctum", "D": "มีก้าน"}, "summary": ["KA ↔ well-differentiated SCC"], "kimg": ["l22_p7"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 7 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 9, "notes": "p8 ลายมือ: <b>“m/c acquired = Nevus (ไฝ) → มักเป็นภายหลังเกิด (ไม่เสี่ยง malignant)”</b>", "stem": "A 25-year-old woman has a small mole on her chin that appeared in childhood and has not changed. What is the risk of malignancy?", "opts": ["It is a premalignant actinic keratosis", "It must be excised immediately", "Low, because most moles are acquired and rarely become malignant", "High, because it is on the face", "High, because every mole eventually becomes melanoma if left long enough"], "ans": 2, "interp": "", "why": "ลายมือ p8: m/c acquired = nevus (ไฝ) → มักเป็นภายหลังเกิด (ไม่เสี่ยง malignant) · congenital จะเสี่ยง melanoma (CMN) · สงสัย CA ถ้ามี cardinal symptoms", "wrong": {"A": "ไม่ใช่", "B": "ไม่มีข้อบ่งชี้", "D": "ตำแหน่งไม่ใช่เกณฑ์", "E": "ผิด"}, "summary": ["Acquired nevus เสี่ยงต่ำ"], "kimg": ["l22_p8"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 8 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 10, "notes": "p8 ลายมือ: <b>“congenital จะเสี่ยง melanoma → Congenital melanocytic nevus (CMN)”</b>", "stem": "A newborn has a 25-cm hairy pigmented lesion over the lower back present at birth. Which risk is most important for counseling?", "opts": ["Risk of spontaneous involution like hemangioma", "Increased risk of melanoma", "No risk because it is congenital", "Risk of keratoacanthoma", "Risk of basal cell carcinoma within months"], "ans": 1, "interp": "", "why": "ลายมือ p8: congenital จะเสี่ยง melanoma → congenital melanocytic nevus (CMN) · 📖 giant CMN (> 20 cm) เสี่ยงสูงสุด", "wrong": {"A": "ไม่ยุบ", "C": "ผิด", "D": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["CMN (โดยเฉพาะ giant) → melanoma"], "kimg": ["l22_p8"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 8 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 11, "notes": "p9: <b>Cardinal signs and symptoms of malignant change in a mole — Change in size, shape, or thickness · Itching · Bleeding / ulceration</b> · ลายมือ: <span class=\"hw\">= ควร bx ส่งตรวจ · โตเร็ว</span>", "stem": "A 40-year-old woman reports that a mole on her arm has grown rapidly, become itchy and bled. What should be done?", "opts": ["Cauterize without histology", "Reassure and review in 5 years", "Shave it off and discard it", "Apply topical steroid", "Biopsy the lesion"], "ans": 4, "interp": "", "why": "p9: cardinal signs of malignant change — change in size (ลายมือ โตเร็ว), itching, bleeding/ulceration (ลายมือ = ควร bx ส่งตรวจ)", "wrong": {"A": "ไม่มีผลชิ้นเนื้อ", "B": "ช้า", "C": "ต้องส่งตรวจ", "D": "ไม่ใช่"}, "summary": ["Cardinal signs → bx"], "kimg": ["l22_p9"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 9 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 12, "notes": "p9: <b>Halo — pink [inflammatory reaction]: early · brown [pigment]: late</b> · <b>Loss of normal surface markings [Skin creases]</b>", "stem": "A 55-year-old man has a mole that has lost its normal skin creases and now has a pink halo around it. How should the pink halo be interpreted?", "opts": ["Evidence of fungal infection", "An early inflammatory reaction suggesting malignant change", "A sign of seborrheic keratosis", "A normal finding in benign moles", "A late sign caused by pigment spreading out from the mole into the skin"], "ans": 1, "interp": "", "why": "p9: loss of normal surface markings [skin creases] · halo pink [inflammatory reaction]: early · brown [pigment]: late", "wrong": {"A": "ไม่ใช่", "C": "ไม่ใช่", "D": "ไม่ใช่", "E": "= brown halo"}, "summary": ["Halo pink = early · brown = late"], "kimg": ["l22_p9"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 9 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 13, "notes": "p10 ลายมือ: <b>“= ก้อน fat → ก้อนโยกไปมาได้ (ไม่ติดกับ skin / subcu ข้างล่าง) · Tx = กรีด (ไม่ต้องทำ skin excision) → เอา lipoma ออก = หายขาด”</b>", "stem": "A 45-year-old man has a soft, painless, lobulated 4-cm mass on his back that moves freely and is not attached to the overlying skin. What is the appropriate surgical approach if he wants it removed?", "opts": ["Incise the skin and deliver the mass without excising skin", "Wide excision with 2-cm margins", "Mohs micrographic surgery", "Needle aspiration only", "Elliptical excision of the overlying skin together with the whole mass"], "ans": 0, "interp": "", "why": "ลายมือ p10: lipoma ที่ชั้น subcu = ก้อน fat → โยกไปมาได้ (ไม่ติดกับ skin/subcu ข้างล่าง) · Tx = กรีด (ไม่ต้องทำ skin excision) → เอา lipoma ออก = หายขาด", "wrong": {"B": "ไม่ใช่มะเร็ง", "C": "ไม่ใช่", "D": "ไม่หาย", "E": "= sebaceous cyst"}, "summary": ["Lipoma: กรีด ควักออก ไม่ต้องตัดผิว"], "kimg": ["l22_p10", "l22_p11"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 10, 11 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 14, "notes": "p10 ลายมือ: <b>“* ถ้าก้อนใหญ่ / โตเร็ว → liposarcoma”</b>", "stem": "A 58-year-old woman has a 12-cm subcutaneous thigh mass that has doubled in size in 3 months. Which diagnosis must be excluded before simple removal?", "opts": ["Skin tag", "Furuncle", "Liposarcoma", "Seborrheic keratosis", "Sebaceous cyst"], "ans": 2, "interp": "", "why": "ลายมือ p10: *ถ้าก้อนใหญ่/โตเร็ว → liposarcoma", "wrong": {"A": "บนผิว", "B": "มีหนอง", "D": "บนผิว", "E": "ติดผิว"}, "summary": ["Lipoma ใหญ่/โตเร็ว → คิด liposarcoma (imaging ก่อน)"], "kimg": ["l22_p10", "l22_p11"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 10, 11 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 15, "notes": "p10 ลายมือ: <b>“in case ก้อนน่ารำคาญ / กดทับ (ไม่เอาออกก็ได้)”</b>", "stem": "A 30-year-old man has a 2-cm asymptomatic lipoma on his forearm and asks whether it must be removed. What is the best advice?", "opts": ["Removal is optional unless it is bothersome or compresses structures", "It must be excised with 1-cm margins", "It should be treated with radiotherapy", "It should be drained", "It must be removed urgently because most lipomas eventually become liposarcoma"], "ans": 0, "interp": "", "why": "ลายมือ p10: in case ก้อนน่ารำคาญ / กดทับ (ไม่เอาออกก็ได้)", "wrong": {"B": "ไม่ใช่มะเร็ง", "C": "ไม่ใช่", "D": "ไม่ใช่ฝี", "E": "lipoma เล็กไม่ใช่มะเร็ง"}, "summary": ["Lipoma เล็ก → เอาออกเมื่อรำคาญ/กดทับ"], "kimg": ["l22_p10", "l22_p11"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 10, 11 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 16, "notes": "p12 ลายมือ: <b>“= Epidermal inclusion cyst · ก้อนติดผิว (ติดรูขุมขน) ไม่ติดข้างล่าง”</b>", "stem": "A 35-year-old man has a 2-cm smooth, firm nodule on his back with a small central dark punctum. The nodule moves with the skin. What is the diagnosis?", "opts": ["Lipoma", "Epidermal inclusion (sebaceous) cyst", "Dermatofibroma", "Keratoacanthoma", "Neurofibroma"], "ans": 1, "interp": "", "why": "ลายมือ p12: sebaceous cyst = epidermal inclusion cyst · ก้อนติดผิว (ติดรูขุมขน) ไม่ติดข้างล่าง · p14 punctum", "wrong": {"A": "ไม่ติดผิว", "C": "ไม่มี punctum", "D": "มี crater keratin", "E": "นุ่ม ไม่มี punctum"}, "summary": ["Punctum + ติดผิว = epidermal cyst"], "kimg": ["l22_p12", "l22_p13"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 12, 13 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 17, "notes": "p13 ลายมือ: <b>“sebaceous cyst จะติดผิวด้านบน ∴ ตอนตัด ต้องเอา skin ข้างบนออกไปด้วย = หายขาด”</b>", "stem": "A 40-year-old woman has had a sebaceous cyst on her neck removed by squeezing out its contents through a small incision. It recurs 6 months later. What was the error?", "opts": ["The cyst wall attached to the overlying skin was not removed", "The cyst should have been treated with a course of oral antibiotics only, without surgery", "The incision was too long", "The cyst should have been irradiated", "A lipoma was mistaken for a cyst"], "ans": 0, "interp": "", "why": "ลายมือ p13: sebaceous cyst จะติดผิวด้านบน ∴ ตอนตัด ต้องเอา skin ข้างบนออกไปด้วย = หายขาด (เหลือผนังถุง → เป็นซ้ำ)", "wrong": {"B": "ไม่หาย", "C": "ไม่ใช่", "D": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["Epidermal cyst: เอาถุงทั้งใบ + skin/punctum"], "kimg": ["l22_p12", "l22_p13"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 12, 13 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 18, "notes": "p14: <b>1. Cross section (Punctum, Cyst) · 2. Injection of local anaesthetic · 3. Elliptical incision · 4. Removal of cyst · 5. Final suture line</b> · ลายมือ: <span class=\"hw\">ตัด punctum ออกด้วย</span>", "stem": "A 32-year-old man undergoes elective excision of a 2-cm epidermal cyst on the back. Which technique is correct?", "opts": ["Excision of the punctum only", "Needle aspiration of the contents", "Linear incision placed away from the punctum, then expression and drainage of the contents", "Incision and packing", "Elliptical skin incision including the punctum, removing the intact cyst"], "ans": 4, "interp": "", "why": "p14: 1 punctum + cyst 2 local anaesthetic 3 elliptical incision 4 removal of cyst 5 final suture line · ลายมือ ตัด punctum ออกด้วย · p15–16 complete excision", "wrong": {"A": "ไม่หมด", "B": "ไม่หาย", "C": "เหลือถุง", "D": "ใช้กับฝี"}, "summary": ["Ellipse รอบ punctum + ถุงทั้งใบ"], "kimg": ["l22_p14", "l22_p15", "l22_p16"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 14, 15, 16 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 19, "notes": "p13 ลายมือ: <b>“in case ก้อนน่ารำคาญ / กดทับ / infx (เสี่ยง infx ซ้ำ)”</b>", "stem": "A 28-year-old woman has an acutely inflamed, fluctuant sebaceous cyst on her back. What is the most appropriate initial management?", "opts": ["Immediate complete excision of the cyst wall through the inflamed, infected skin today", "Mohs micrographic surgery", "Incision and drainage now, with complete excision after inflammation settles", "Radiotherapy", "Observation without drainage"], "ans": 2, "interp": "", "why": "p13 ลายมือ: ตัดในกรณีน่ารำคาญ/กดทับ/infx · 📖 cyst อักเสบเป็นหนอง → I&D ก่อน แล้วตัดถุงออกทีหลัง (ตอนอักเสบถุงเปื่อย เอาไม่หมด) · นอกสไลด์: Sabiston: infected cyst → I&D then delayed excision", "wrong": {"A": "ถุงเปื่อยเอาไม่หมด", "B": "ไม่ใช่", "D": "ไม่ใช่", "E": "หนองไม่ระบาย"}, "summary": ["Infected cyst → I&D ก่อน แล้ว excise ภายหลัง"], "kimg": ["l22_p14", "l22_p15", "l22_p16"], "tags": ["Plastic", "Surgical infection"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 14, 15, 16 · ไม่มีสัญลักษณ์คณะ · ลายมือ · นอกสไลด์"}, {"n": 20, "notes": "p18: <b>Haemangioma — Present soon after birth · Rapid cellular proliferation over the first year of life · 90% involute over time</b>", "stem": "A 6-week-old girl has a bright red raised lesion on her arm that was not visible at birth and is now growing quickly. What is the expected natural history?", "opts": ["Rapid growth during the first year followed by gradual involution", "Immediate regression within 2 weeks", "Growth only in proportion to the child, with no rapid phase and no involution later", "Malignant transformation in adolescence", "Continuous rapid growth throughout childhood"], "ans": 0, "interp": "", "why": "p18: haemangioma — present soon after birth · rapid cellular proliferation over the first year of life · 90% involute over time (ลายมือ → เหลือ fibrofatty tissue)", "wrong": {"B": "ไม่ใช่", "C": "= vascular malformation", "D": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["Hemangioma: โตเร็วขวบปีแรก → ยุบ"], "kimg": ["l22_p17", "l22_p18"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 17, 18 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 21, "notes": "p18 ลายมือ: <b>“→ เหลือ fibrofatty tissue → อาจมาแต่ผิวไม่สวย / หายแล้วผิวเรียบไปเลย”</b>", "stem": "A 7-year-old boy had a facial hemangioma in infancy that has now involuted. What may remain at the site?", "opts": ["Fibrofatty tissue with altered skin texture", "A lipoma that keeps growing", "Completely normal skin in every case, with no change in texture", "A malignant vascular tumor", "An arteriovenous malformation"], "ans": 0, "interp": "", "why": "ลายมือ p18: involute → เหลือ fibrofatty tissue → อาจมาแต่ผิวไม่สวย / หายแล้วผิวเรียบไปเลย", "wrong": {"B": "ไม่ใช่", "C": "ไม่ทุกราย", "D": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["Involuted hemangioma → fibrofatty residuum"], "kimg": ["l22_p17", "l22_p18"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 17, 18 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 22, "notes": "p18 ลายมือ: <b>“e.g. อยู่บนเปลือกตาเด็ก → โตเร็ว … ใช้ตาข้างเดียวเกิน 3 mo = จะไม่ใช้ตาอีกข้างแม้จะเปิดตาทีหลัง (ตาขี้เกียจ)”</b>", "stem": "A 2-month-old infant has a rapidly enlarging hemangioma of the upper eyelid that is closing the eye. Why is urgent treatment needed?", "opts": ["Visual deprivation for more than a few months can cause permanent amblyopia", "It is a venous malformation", "The lesion will become malignant", "It never involutes", "It causes high-output heart failure in all infants with periocular lesions"], "ans": 0, "interp": "", "why": "ลายมือ p18: อยู่บนเปลือกตาเด็ก → โตเร็ว = หลับตาไม่ได้/บังตา 1 ข้าง → ใช้ตาข้างเดียวเกิน 3 mo = จะไม่ใช้ตาอีกข้าง (ตาขี้เกียจ) ∴ ตำแหน่งสำคัญ → ยา/Sx", "wrong": {"B": "เป็น hemangioma", "C": "ไม่ใช่", "D": "hemangioma ยุบได้ — เหตุที่รักษาคือตำแหน่ง", "E": "ไม่ทุกราย"}, "summary": ["Periocular hemangioma → amblyopia → treat"], "kimg": ["l22_p18"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 18 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 23, "notes": "p18 ลายมือ: <b>“∴ อยู่ตำแหน่งสำคัญ e.g. eyelids, หน้าหู, upper airway obstruct = ให้ steroid / IFN / Sx · ปิดรูหู → ไม่เรียนรู้ / ไม่พูด → ใบ้เทียม”</b>", "stem": "A 3-month-old girl has a proliferating hemangioma occluding the external ear canal. According to current guidelines, which is the first-line medical treatment?", "opts": ["Observation until age 9", "Oral propranolol", "Radiotherapy", "Wide surgical excision with margins", "Interferon alpha"], "ans": 1, "interp": "", "why": "ลายมือ p18: ตำแหน่งสำคัญ (หู ปิดรูหู → ไม่ได้ยิน/ใบ้เทียม) = ให้ steroid/IFN/Sx — 📘 AAP 2019: first-line = oral propranolol (IFN เลิกใช้) · นอกสไลด์: AAP CPG 2019", "wrong": {"A": "ปิดหูเสียการเรียนรู้ภาษา", "C": "ไม่ใช่", "D": "ไม่จำเป็น", "E": "เลิกใช้ในทารก"}, "summary": ["IH ตำแหน่งอันตราย → propranolol"], "kimg": ["l22_p18"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 18 · ไม่มีสัญลักษณ์คณะ · ลายมือ · นอกสไลด์", "trap": "สไลด์ให้ IFN/steroid แต่ guideline ใหม่ = propranolol"}, {"n": 24, "notes": "p19: <b>Vascular malformation — Structural abnormalities formed during fetal development · Grow in proportion to the body · Never involute</b>", "stem": "A 20-year-old man has had a purple facial lesion since birth that has grown in proportion with his body without any period of rapid growth or regression. What is the diagnosis?", "opts": ["Vascular malformation", "Keratoacanthoma", "Infantile hemangioma", "Melanoma", "Pyogenic granuloma"], "ans": 0, "interp": "", "why": "p19: vascular malformation — structural abnormalities formed during fetal development · grow in proportion to the body (ลายมือ โตตามขนาดตัว ไม่มีช่วงโตเร็ว) · never involute", "wrong": {"B": "ไม่ใช่", "C": "มีช่วงโตเร็วและยุบ", "D": "ไม่ใช่", "E": "โตเร็วระยะสั้น"}, "summary": ["VM: มีตั้งแต่เกิด โตตามตัว ไม่ยุบ"], "kimg": ["l22_p17", "l22_p19"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 17, 19 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 25, "notes": "p17 ลายมือ: <b>Vascular malformation = เกิดใน 2 wk หลังคลอด → ค่อย ๆ โตตามตัว (ไม่มีช่วงโตเร็ว) → ไม่หายเอง</b> · p19: <b>Never involute</b>", "stem": "Parents ask whether their 4-year-old son's port-wine stain on the cheek will fade like a hemangioma. What is the correct answer?", "opts": ["Yes, it disappears in the first year", "Yes, 90% involute by age 9", "It becomes a hemangioma", "No, vascular malformations never involute", "It involutes only after several sessions of laser treatment"], "ans": 3, "interp": "", "why": "p17/p19: vascular malformation = ไม่หายเอง (never involute) · hemangioma = 90% involute", "wrong": {"A": "ไม่ใช่", "B": "= hemangioma", "C": "ไม่ใช่", "E": "laser ทำให้จางแต่ไม่ใช่ involute"}, "summary": ["Capillary malformation (port-wine) ไม่ยุบ"], "kimg": ["l22_p17", "l22_p19"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 17, 19 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 26, "notes": "p19 ลายมือ: <b>“High flow = เอา embolize อุด / ฉีด sclerosing agent or absolute alcohol ให้ฝ่อ แล้วตัดออก” · “คลำได้ pulse / thrills / bruit → arterial malformation”</b>", "stem": "A 25-year-old woman has a warm vascular lesion on the forearm with a palpable thrill and bruit. What is the most appropriate treatment strategy?", "opts": ["Observation until it involutes during childhood, as most do", "Oral propranolol until the thrill disappears", "Compression stockings only", "Embolization or sclerosant injection followed by surgical excision", "Surface laser only"], "ans": 3, "interp": "", "why": "ลายมือ p19: high flow — คลำได้ pulse/thrills/bruit → arterial malformation · high flow = เอา embolize อุด/ฉีด sclerosing agent or absolute alcohol ให้ฝ่อ แล้วตัดออก", "wrong": {"A": "ไม่ยุบ", "B": "ใช้กับ hemangioma", "C": "ไม่พอ", "E": "= capillary"}, "summary": ["High-flow (AVM) → embolize แล้วตัด"], "kimg": ["l22_p19"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 19 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 27, "notes": "p19 ลายมือ: <b>“capillary : สีแดงเข้ม · capillary : ตื้น → ใช้ laser ยิงจากด้านนอก”</b>", "stem": "A 10-year-old girl has a flat, dark red, superficial vascular malformation on her cheek. Which treatment is most suitable?", "opts": ["Oral propranolol", "Embolization followed by wide excision", "Observation until it involutes", "Laser applied from the skin surface", "Wide excision with skin graft as first line"], "ans": 3, "interp": "", "why": "ลายมือ p19: low flow — capillary: สีแดงเข้ม · ตื้น → ใช้ laser ยิงจากด้านนอก (📖 pulsed dye laser)", "wrong": {"A": "ใช้กับ hemangioma", "B": "= high flow", "C": "ไม่ยุบ", "E": "ไม่ใช่ first line"}, "summary": ["Capillary malformation → surface laser"], "kimg": ["l22_p19"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 19 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 28, "notes": "p19 ลายมือ: <b>“venous : สีม่วงน้ำเงินเข้ม · lymphatic : สี normal skin” · “Low flow — venous : ลึกหน่อย → ตัดทิ้ง / แยง laser แบบ fiber optic ไปเผาแล้วค่อยตัด”</b>", "stem": "A 30-year-old man has a soft, compressible, blue-purple swelling of the forearm that enlarges when the arm hangs down. There is no thrill. What type of lesion is this?", "opts": ["Lymphatic malformation", "High-flow arteriovenous malformation", "Lipoma", "Infantile hemangioma", "Low-flow venous malformation"], "ans": 4, "interp": "", "why": "ลายมือ p19: low flow — venous: สีม่วงน้ำเงินเข้ม (ลึกหน่อย → ตัดทิ้ง/แยง laser fiber optic ไปเผาแล้วค่อยตัด) · lymphatic: สี normal skin", "wrong": {"A": "สีผิวปกติ", "B": "มี thrill/bruit", "C": "ไม่ม่วง ไม่ยุบตามท่า", "D": "ไม่ใช่วัยนี้"}, "summary": ["Venous malformation: ม่วงน้ำเงิน กดยุบ"], "kimg": ["l22_p19"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 19 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 29, "notes": "p19 ลายมือ: <b>“ปากเหี่ยวแล้ว = adult → hemang ควรฝ่อแล้ว ∴ น่าจะเป็น malform · สีม่วงน้ำเงิน = venous malformation”</b>", "stem": "A 55-year-old woman has a small blue-purple compressible nodule on her lower lip that she has had since childhood. What is the most likely diagnosis?", "opts": ["Squamous cell carcinoma", "Pyogenic granuloma", "Infantile hemangioma", "Venous malformation", "Melanoma"], "ans": 3, "interp": "", "why": "ลายมือ p19: ปากเหี่ยวแล้ว = adult → hemang ควรฝ่อแล้ว ∴ น่าจะเป็น malform · สีม่วงน้ำเงิน = venous malformation", "wrong": {"A": "ไม่ใช่", "B": "เกิดเร็ว", "C": "ผู้ใหญ่ hemangioma ควรยุบแล้ว", "E": "ไม่ใช่"}, "summary": ["ผู้ใหญ่ + ม่วงน้ำเงิน + มีตั้งแต่เด็ก = VM"], "kimg": ["l22_p19"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 19 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "img": ["l22_p19"]}, {"n": 30, "notes": "p20 ลายมือ: <b>“Tx = excision (not wide excision) · ไม่ต้องเอาเนื้อดีออกเยอะ”</b>", "stem": "A 60-year-old man has a 1-cm biopsy-proven actinic keratosis on the scalp, and surgical removal is chosen. Which surgical approach is appropriate?", "opts": ["Amputation of the scalp segment", "Excision with a narrow margin, without wide excision", "No treatment because it is benign", "Wide excision with 2-cm margins and lymph node dissection", "Mohs surgery for every lesion"], "ans": 1, "interp": "", "why": "ลายมือ p20: premalignant conditions — Tx = excision (not wide excision) ไม่ต้องเอาเนื้อดีออกเยอะ", "wrong": {"A": "ไม่ใช่", "C": "เป็น premalignant", "D": "เกินจำเป็น", "E": "ไม่จำเป็นทุกราย"}, "summary": ["Premalignant → excision (not wide)"], "kimg": ["l22_p20"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 20 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 31, "notes": "p22 ลายมือ: <b>“เสี่ยง basal cell carcinoma → ตัด lesion พอ (ไม่ต้อง wide excision)”</b>", "stem": "A 15-year-old girl has a nevus sebaceous of the scalp. Her parents ask how wide the excision should be. What is the best answer?", "opts": ["A 1-cm margin, the same as for squamous cell carcinoma of the skin", "Excision of the lesion alone is enough; wide margins are not needed", "A 2-cm margin is required", "No treatment is ever needed", "Mohs surgery is mandatory"], "ans": 1, "interp": "", "why": "ลายมือ p20: premalignant → excision (not wide) · p22: เสี่ยง BCC → ตัด lesion พอ (ไม่ต้อง wide excision)", "wrong": {"A": "เกิน", "C": "เกิน", "D": "premalignant ควรตัด", "E": "ไม่จำเป็น"}, "summary": ["Premalignant: ตัด lesion พอ"], "kimg": ["l22_p20"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 20 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 32, "notes": "p21: <b>Bowen's disease on leg</b> · ลายมือ: <span class=\"hw\">เสี่ยง squamous cell carcinoma · สะเก็ด / ปื้นแดง ๆ / แผลตื้น ๆ</span>", "stem": "A 70-year-old woman has a well-demarcated, scaly red patch on her leg that has slowly enlarged over years despite steroid creams. Biopsy shows full-thickness epidermal atypia without invasion. Which cancer may this lesion progress to?", "opts": ["Merkel cell carcinoma", "Liposarcoma", "Malignant melanoma", "Basal cell carcinoma", "Squamous cell carcinoma"], "ans": 4, "interp": "", "why": "ลายมือ p21: Bowen's disease → เสี่ยง squamous cell carcinoma · ลักษณะ สะเก็ด/ปื้นแดง ๆ/แผลตื้น ๆ (📖 = SCC in situ)", "wrong": {"A": "ไม่ใช่", "B": "ไม่ใช่", "C": "ไม่ใช่", "D": "= nevus sebaceous"}, "summary": ["Bowen = SCC in situ → SCC"], "kimg": ["l22_p21"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 21 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 33, "notes": "p21 ลายมือ: <b>เสี่ยง squamous cell carcinoma</b> · p20 ลายมือ: <b>Tx = excision (not wide excision)</b>", "stem": "A 64-year-old man with past arsenic exposure has a red, scaly plaque on the trunk diagnosed as Bowen's disease. What is the appropriate management?", "opts": ["Radiotherapy to the whole trunk", "Wide excision with lymph node dissection", "Observation only", "Oral antifungal treatment", "Excision of the lesion"], "ans": 4, "interp": "", "why": "p20–21: premalignant (Bowen → SCC) → excision (not wide)", "wrong": {"A": "เกิน", "B": "เกิน", "C": "มีโอกาสเป็นมะเร็ง", "D": "ไม่ใช่"}, "summary": ["Bowen → excision"], "kimg": ["l22_p21"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 21 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 34, "notes": "p22: <b>Nevus sebaceous of Jadassohn</b> · ลายมือ: <span class=\"hw\">เสี่ยง basal cell carcinoma → ตัด lesion พอ · มักเกิด at head &amp; neck area · ผื่นเล็ก ๆ ติดกันตรง head &amp; neck (cobblestone) นูน ๆ คล้าย skin</span>", "stem": "A 12-year-old girl has a hairless, yellow-orange, slightly raised plaque on her scalp present since birth, with a cobblestone surface. Which malignancy is classically associated?", "opts": ["Squamous cell carcinoma", "Basal cell carcinoma", "Malignant melanoma", "Liposarcoma", "Dermatofibrosarcoma"], "ans": 1, "interp": "", "why": "ลายมือ p22: nevus sebaceous of Jadassohn → เสี่ยง basal cell carcinoma · มักเกิด at head & neck area · ผื่นเล็ก ๆ ติดกัน (cobblestone) นูน ๆ", "wrong": {"A": "= Bowen/AK", "C": "= CMN", "D": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["Nevus sebaceous → BCC"], "kimg": ["l22_p22", "l22_p70"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 22, 70 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 35, "notes": "p70 ลายมือ: <b>“nervous sebaceous of Jadassohn — เป็น premalignant → excision”</b>", "stem": "A 20-year-old man has a congenital cobblestone plaque on the scalp shown in a clinical photograph as benign lesion 'B'. What is the recommended management?", "opts": ["Excision because it is premalignant", "Wide excision with 2-cm margins", "Oral isotretinoin", "No treatment because it is purely benign", "Laser ablation of the surface only"], "ans": 0, "interp": "", "why": "ลายมือ p70 (B): nevus sebaceous of Jadassohn → เป็น premalignant → excision", "wrong": {"B": "เกิน", "C": "ไม่ใช่", "D": "premalignant", "E": "ไม่ครบ"}, "summary": ["Nevus sebaceous → excision"], "kimg": ["l22_p22", "l22_p70"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 22, 70 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "img": ["l22_p70"]}, {"n": 36, "notes": "p23: <b>Actinic Keratosis</b> · ลายมือ: <span class=\"hw\">= m/c premalignant lesion · เสี่ยง squamous cell CA · e.g. ปื้นแดง / patch / แผลตื้น ๆ</span>", "stem": "A 68-year-old farmer has multiple rough, red, scaly patches on his sun-exposed forehead and the backs of his hands. What is the most common premalignant skin lesion of this type, and to what may it progress?", "opts": ["Lipoma, which may progress to liposarcoma", "Nevus sebaceous of Jadassohn, which may progress to basal cell carcinoma", "Actinic keratosis, which may progress to squamous cell carcinoma", "Skin tag, which may progress to squamous cell carcinoma", "Seborrheic keratosis, which may progress to melanoma"], "ans": 2, "interp": "", "why": "ลายมือ p23: actinic keratosis = m/c premalignant lesion · เสี่ยง squamous cell CA · e.g. ปื้นแดง/patch/แผลตื้น ๆ", "wrong": {"A": "ไม่ใช่", "B": "หนังศีรษะตั้งแต่เกิด", "D": "benign", "E": "SK benign"}, "summary": ["AK = premalignant ที่พบบ่อยสุด → SCC"], "kimg": ["l22_p23"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 23 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 37, "notes": "p23 ลายมือ: <b>“cf. seborrheic keratosis → benign” · “= m/c premalignant lesion”</b>", "stem": "A 75-year-old woman has two lesions: a brown, stuck-on plaque on her back and a rough red scaly patch on her nose. Which statement is correct?", "opts": ["The red scaly patch is premalignant, whereas the stuck-on plaque is benign", "The stuck-on plaque is premalignant, whereas the red scaly patch is benign", "Both are premalignant", "Both are basal cell carcinomas", "Both are benign"], "ans": 0, "interp": "", "why": "ลายมือ p23: actinic keratosis = m/c premalignant → SCC · cf. seborrheic keratosis → benign", "wrong": {"B": "สลับ", "C": "SK benign", "D": "ไม่ใช่", "E": "AK premalignant"}, "summary": ["AK premalignant vs SK benign"], "kimg": ["l22_p23"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 23 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 38, "notes": "p24: <b>Approximately 77% are BCC · 20% are SCC · 3% are MM and rare tumor</b>", "stem": "A 66-year-old man is diagnosed with a primary skin cancer. Without other information, which type is statistically most likely?", "opts": ["Malignant melanoma", "Squamous cell carcinoma", "Basal cell carcinoma", "Merkel cell carcinoma", "Cutaneous lymphoma"], "ans": 2, "interp": "", "why": "p24: approximately 77% BCC · 20% SCC · 3% MM and rare tumor", "wrong": {"A": "3%", "B": "20%", "D": "rare", "E": "rare"}, "summary": ["BCC 77% > SCC 20% > MM 3%"], "kimg": ["l22_p24"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 24 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 39, "notes": "p24 ลายมือ: <b>ลูกศร “common” ชี้ BCC · “aggressive” ชี้ Malignant melanoma</b>", "stem": "Three patients aged 60, 62 and 65 years have basal cell carcinoma, squamous cell carcinoma and melanoma respectively, each of similar size. Which tumor is the most aggressive?", "opts": ["Basal cell carcinoma", "Malignant melanoma", "Squamous cell carcinoma", "All are equally aggressive", "Aggressiveness depends only on patient age"], "ans": 1, "interp": "", "why": "ลายมือ p24: ลูกศร common ↑ (BCC พบบ่อยสุด) · aggressive ↓ (MM ร้ายแรงสุด)", "wrong": {"A": "น้อยสุด", "C": "กลาง", "D": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["Common: BCC · aggressive: MM"], "kimg": ["l22_p24"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 24 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 40, "notes": "p25: <b>Chemical exposure</b> · ลายมือ: <span class=\"hw\">e.g. เอาปูนที่ใช้เคี้ยวหมากมา… → chronic irritation · arsenic</span>", "stem": "A 60-year-old woman has chewed betel nut with lime paste for 40 years and applies the lime paste to minor wounds. Which mechanism links this habit to skin and lip cancer?", "opts": ["DNA repair defect", "Viral infection", "Immunosuppression", "Ultraviolet A exposure", "Chronic chemical irritation"], "ans": 4, "interp": "", "why": "ลายมือ p25: chemical exposure e.g. เอาปูนที่ใช้เคี้ยวหมากมากัดแผล → chronic irritation; arsenic", "wrong": {"A": "= XP", "B": "ไม่ใช่", "C": "ไม่ใช่", "D": "UVA = เหี่ยว"}, "summary": ["หมาก/ปูน → chronic irritation"], "kimg": ["l22_p25"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 25 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 41, "notes": "p25: <b>Xeroderma pigmentosum</b> <span class=\"hw\">DNA repair defect</span>", "stem": "A 9-year-old boy with severe sun sensitivity and freckling has already developed several skin cancers. Which defect underlies his condition?", "opts": ["Absence of sebaceous glands", "Overproduction of melanin", "Immunoglobulin deficiency", "Defective DNA repair", "Collagen synthesis defect"], "ans": 3, "interp": "", "why": "ลายมือ p25: xeroderma pigmentosum = DNA repair defect", "wrong": {"A": "ไม่ใช่", "B": "ไม่ใช่", "C": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["XP → DNA repair defect"], "kimg": ["l22_p25"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 25 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 42, "notes": "p25 ลายมือ: <b>“Immunosuppression → ต้องระวังถ้าคนไข้เป็นแผล 3–4 wk แล้วไม่หาย → ลอง bx ดู skin cancer”</b>", "stem": "A 50-year-old kidney transplant recipient on immunosuppressants has a small leg ulcer that has not healed after 4 weeks. What is the most appropriate step?", "opts": ["Biopsy to exclude skin cancer", "Apply topical steroid", "Stop all immunosuppressants", "Continue dressings for another 6 months", "Amputate the leg"], "ans": 0, "interp": "", "why": "ลายมือ p25: immunosuppression → ต้องระวังถ้าคนไข้เป็นแผล 3–4 wk แล้วไม่หาย → ลอง bx ดู skin cancer", "wrong": {"B": "ไม่ใช่", "C": "อันตราย", "D": "ช้า", "E": "ไม่ใช่"}, "summary": ["Immunosuppressed + แผลไม่หาย 3–4 wk → bx"], "kimg": ["l22_p25"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 25 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 43, "notes": "p25 ลายมือ: <b>“UV A = เหี่ยว · UV B = skin cancer”</b>", "stem": "A 35-year-old lifeguard asks which component of sunlight is most responsible for skin cancer, compared with photoaging. What is the best answer?", "opts": ["UVB mainly causes skin cancer, whereas UVA mainly causes wrinkling", "Neither causes cancer", "Visible light causes cancer", "UVA mainly causes skin cancer, whereas UVB mainly causes wrinkling and photoaging", "Infrared light causes cancer"], "ans": 0, "interp": "", "why": "ลายมือ p25: UV A = เหี่ยว · UV B = skin cancer", "wrong": {"B": "ผิด", "C": "ไม่ใช่", "D": "สลับ", "E": "ไม่ใช่"}, "summary": ["UVA aging · UVB cancer"], "kimg": ["l22_p25"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 25 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "trap": "สลับ UVA/UVB"}, {"n": 44, "notes": "p26: <b>Basal cell carcinoma — Commonly appear in the shade area</b> · ลายมือ: <span class=\"hw\">= ตรงที่โดนแดด : ตีนผม – ริมฝีปากบน · cf. ริมฝีปากล่าง → squamous cell CA</span>", "stem": "A 70-year-old woman has a pearly nodule on the side of her nose, above a line from the earlobe to the corner of the mouth. Which cancer is most likely at this site?", "opts": ["Melanoma", "Squamous cell carcinoma", "Marjolin's ulcer", "Basal cell carcinoma", "Liposarcoma"], "ans": 3, "interp": "", "why": "p26: BCC commonly appear in the shade area (ลายมือ = ตรงที่โดนแดด : ตีนผม – ริมฝีปากบน) · cf. ริมฝีปากล่าง → SCC", "wrong": {"A": "ไม่ใช่", "B": "ริมฝีปากล่าง/หลังมือ", "C": "แผลเรื้อรัง", "E": "ไม่ใช่"}, "summary": ["ตีนผม–ริมฝีปากบน = BCC"], "kimg": ["l22_p26", "l22_p38"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 26, 38 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 45, "notes": "p38 ลายมือ: <b>“upper lip → basal cell carcinoma มากกว่า ∵ เจอแดด · lower lips → squamous cell carcinoma มากกว่า ∵ เจอ irritation e.g. บุหรี่, หมาก”</b>", "stem": "A 66-year-old man has a chronic ulcer on the lip. On which part of the lip is squamous cell carcinoma more common, compared with basal cell carcinoma?", "opts": ["Only the corners of the mouth", "Lower lip for squamous cell carcinoma; upper lip for basal cell carcinoma", "Neither occurs on the lips", "Upper lip for squamous cell carcinoma; lower lip for basal cell carcinoma", "Both are equally common on both lips"], "ans": 1, "interp": "", "why": "ลายมือ p38: upper lip → BCC มากกว่า ∵ เจอแดด · lower lips → SCC มากกว่า ∵ เจอ irritation e.g. บุหรี่, หมาก", "wrong": {"A": "ไม่ใช่", "C": "ผิด", "D": "สลับ", "E": "ไม่ใช่"}, "summary": ["ริมฝีปากบน BCC · ล่าง SCC"], "kimg": ["l22_p26", "l22_p38", "l22_p39", "l22_p40"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 26, 38, 39, 40 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "trap": "สลับบน/ล่าง"}, {"n": 46, "notes": "p27 ลายมือ: <b>“★ telangiectasia (ก้อนที่เห็น capillary บนก้อน)”</b> · p31: <b>roll edge · ขอบเงา มัน ๆ</b>", "stem": "A 72-year-old man has a slow-growing, shiny, pearly nodule on the cheek with a rolled border and fine superficial blood vessels over its surface. What is the most likely diagnosis?", "opts": ["Keratoacanthoma", "Seborrheic keratosis", "Lipoma", "Basal cell carcinoma", "Squamous cell carcinoma"], "ans": 3, "interp": "", "why": "p27/p31–32: nodular BCC [central breakdown and ulceration] · ลายมือ ★ telangiectasia (ก้อนที่เห็น capillary บนก้อน) · roll edge · ขอบเงา มัน ๆ (pearl colored)", "wrong": {"A": "keratin plug", "B": "stuck-on", "C": "ใต้ผิว", "E": "everted edge necrotic base"}, "summary": ["BCC: pearly + rolled edge + telangiectasia"], "kimg": ["l22_p27", "l22_p31", "l22_p32"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 27, 31, 32 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 47, "notes": "p32 ลายมือ: <b>“Asian type = ก้อนที่มี pigment · ขอบเงา (pearl colored) + roll edge”</b>", "stem": "A 68-year-old Thai woman has a black, shiny nodule with a rolled pearly border near the inner canthus. Melanoma is considered, but which diagnosis is common in Asian patients and fits this appearance?", "opts": ["Seborrheic keratosis", "Keratoacanthoma", "Squamous cell carcinoma", "Venous malformation", "Pigmented basal cell carcinoma"], "ans": 4, "interp": "", "why": "ลายมือ p32: Asian type = ก้อนที่มี pigment · ขอบเงา (pearl colored) + roll edge = pigmented BCC", "wrong": {"A": "ไม่มีขอบมุก", "B": "keratin plug", "C": "ไม่ดำ ขอบ everted", "D": "นุ่มกดยุบ"}, "summary": ["Asian BCC มักมี pigment"], "kimg": ["l22_p27", "l22_p31", "l22_p32"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 27, 31, 32 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "img": ["l22_p32"]}, {"n": 48, "notes": "p32 ลายมือ: <b>ขอบเงา (pearl colored) + roll edge</b> · p27: <b>telangiectasia</b>", "stem": "A 59-year-old man has a pigmented lesion on his cheek. Which feature favors pigmented basal cell carcinoma over melanoma?", "opts": ["Irregular notched border", "Satellite pigmented lesions spreading around the main lesion", "A pearly rolled border with telangiectasia", "Asymmetry with multiple colors within the lesion", "Rapid growth over weeks"], "ans": 2, "interp": "", "why": "p31–32 ลายมือ: BCC = ขอบเงา (pearl) + roll edge + telangiectasia (p27) · ABCD (asymmetry, border irregularity, color heterogeneity) = melanoma", "wrong": {"A": "= melanoma", "B": "= melanoma", "D": "= melanoma", "E": "ไม่จำเพาะ"}, "summary": ["Pearly rolled border → BCC"], "kimg": ["l22_p27", "l22_p31", "l22_p32"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 27, 31, 32 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 49, "notes": "p29: <b>Superficial basal cell carcinoma [spreading flat red plaque]</b> · ลายมือ: <span class=\"hw\">ปื้น ๆ</span>", "stem": "A 62-year-old man has a slowly enlarging, flat, red, slightly scaly plaque on his back with a thin raised edge. Biopsy shows basal cell carcinoma. Which subtype is this?", "opts": ["Superficial basal cell carcinoma", "Sclerotic basal cell carcinoma", "Pigmented basal cell carcinoma", "Rodent ulcer", "Nodular basal cell carcinoma"], "ans": 0, "interp": "", "why": "p29: superficial BCC [spreading flat red plaque] (ลายมือ ปื้น ๆ)", "wrong": {"B": "ยุบขาว ขอบไม่ชัด", "C": "มีสี", "D": "แผลกินลึก", "E": "ก้อนนูน"}, "summary": ["Superficial BCC = ปื้นแดงแบน"], "kimg": ["l22_p28", "l22_p29", "l22_p30"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 28, 29, 30 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 50, "notes": "p30: <b>Sclerotic basal cell carcinoma [depress white plaque]</b> · ลายมือ: <span class=\"hw\">ขอบไม่ค่อยชัด</span>", "stem": "A 70-year-old woman has a depressed, white, scar-like plaque on the forehead with poorly defined edges. Biopsy shows basal cell carcinoma. Why is this subtype difficult to treat?", "opts": ["It responds only to chemotherapy", "It metastasizes early to the lungs and regional lymph nodes", "Its borders are ill-defined and it extends beyond what is visible", "It regresses spontaneously", "It is always pigmented"], "ans": 2, "interp": "", "why": "p30: sclerotic BCC [depress white plaque] · ลายมือ ขอบไม่ค่อยชัด → 📖 ลามใต้ผิวเกินที่เห็น → high-risk → Mohs", "wrong": {"A": "ไม่ใช่", "B": "BCC แทบไม่แพร่กระจาย", "D": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["Sclerotic/morpheaform: ขอบไม่ชัด → Mohs"], "kimg": ["l22_p28", "l22_p29", "l22_p30"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 28, 29, 30 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 51, "notes": "p27 ลายมือ: <b>“biopsy ขอบ ให้ติดเนื้อดีด้วย → ดู transition”</b>", "stem": "A 75-year-old man has a 2-cm ulcerated nodule on the temple suspected to be basal cell carcinoma. An incisional biopsy is planned. Where should the biopsy be taken?", "opts": ["From the necrotic slough", "From a nearby lymph node", "From the deepest point in the center of the ulcer only, avoiding the edge", "From normal skin 5 cm away", "At the edge, including adjacent normal skin to show the transition"], "ans": 4, "interp": "", "why": "ลายมือ p27: biopsy ขอบ ให้ติดเนื้อดีด้วย → ดู transition", "wrong": {"A": "ไม่ช่วย", "B": "ไม่ใช่ขั้นแรก", "C": "ได้แต่ necrosis", "D": "ไม่ใช่"}, "summary": ["Bx ขอบ + เนื้อดี"], "kimg": ["l22_p27"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 27 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 52, "notes": "p27 ลายมือ: <b>“biopsy ขอบ ให้ติดเนื้อดีด้วย → ดู transition”</b>", "stem": "A 64-year-old woman has a chronic nonhealing ulcer of the cheek. A biopsy taken from the center of the ulcer shows only necrotic debris. What is the next step?", "opts": ["Perform wide excision with 2-cm margins without a tissue diagnosis", "Diagnose a benign ulcer and discharge", "Apply antibiotic ointment for 6 months", "Start chemotherapy", "Repeat biopsy from the ulcer margin including normal skin"], "ans": 4, "interp": "", "why": "ลายมือ p27: bx ขอบให้ติดเนื้อดี → ดู transition (กลางแผลได้แต่เนื้อตาย)", "wrong": {"A": "ไม่ควร", "B": "ยังไม่ได้วินิจฉัย", "C": "ช้า", "D": "ไม่มี dx"}, "summary": ["Bx ผิดตำแหน่ง → ทำซ้ำที่ขอบ"], "kimg": ["l22_p27"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 27 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 53, "notes": "p33 ลายมือ: <b>“Rodent ulcer → in case แผลแตกเป็น ulcer (พื้นแผลสะอาด)”</b>", "stem": "An 80-year-old woman has a large, deep ulcer on the face that has destroyed the eyelids over years. The ulcer base is relatively clean and the edges are rolled. There are no palpable nodes. What is the most likely diagnosis?", "opts": ["Marjolin's ulcer", "Rodent ulcer of basal cell carcinoma", "Pressure injury", "Pyoderma gangrenosum", "Venous ulcer"], "ans": 1, "interp": "", "why": "ลายมือ p33: rodent ulcer → in case แผลแตกเป็น ulcer (พื้นแผลสะอาด) · p34 BCC กินลึก", "wrong": {"A": "แผลเรื้อรังเดิม", "C": "เหนือกระดูก", "D": "ไม่ใช่", "E": "ขา"}, "summary": ["Rodent ulcer = BCC แผลกินลึก พื้นสะอาด ไม่ค่อยแพร่"], "kimg": ["l22_p33", "l22_p34"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 33, 34 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "img": ["l22_p34"]}, {"n": 54, "notes": "p33 ลายมือ: <b>Rodent ulcer</b>", "stem": "A 78-year-old man has a long-standing ulcerated basal cell carcinoma eroding the cheek and nose. Which behavior is typical of this tumor?", "opts": ["Extensive local destruction with rare distant metastasis", "Rapid lymph node spread in most cases, needing neck dissection", "Transformation into melanoma", "Early metastasis to the lungs", "Spontaneous regression"], "ans": 0, "interp": "", "why": "p33–34: rodent ulcer (BCC) — กินลึกทำลายเนื้อเยื่อเฉพาะที่ · 📖 แทบไม่แพร่กระจาย", "wrong": {"B": "ไม่ใช่ (SCC มากกว่า)", "C": "ไม่ใช่", "D": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["BCC: locally destructive, rarely metastasizes"], "kimg": ["l22_p33", "l22_p34"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 33, 34 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 55, "notes": "p35: <b>Squamous cell carcinoma — Everted and rise edge with necrotic tissue at base</b> · ลายมือ: <span class=\"hw\">ขอบยก + everted</span>", "stem": "A 70-year-old farmer has a 2-cm ulcer on the dorsum of the hand with everted, raised edges and necrotic tissue in the base. What is the most likely diagnosis?", "opts": ["Basal cell carcinoma", "Seborrheic keratosis", "Squamous cell carcinoma", "Lipoma", "Folliculitis"], "ans": 2, "interp": "", "why": "p35: SCC — everted and rise edge with necrotic tissue at base (ลายมือ ขอบยก + everted)", "wrong": {"A": "rolled pearly edge พื้นสะอาด", "B": "ไม่ใช่แผล", "D": "ใต้ผิว", "E": "ตุ่มหนอง"}, "summary": ["SCC: everted edge + necrotic base"], "kimg": ["l22_p35", "l22_p37", "l22_p41", "l22_p42"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 35, 37, 41, 42 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "img": ["l22_p35"]}, {"n": 56, "notes": "p73 ลายมือ: <b>“squamous cell CA — base สกปรก · basal cell CA — ขอบมัน”</b>", "stem": "Two elderly patients have ulcerated facial tumors. One has a clean base with a shiny rolled border; the other has a dirty, necrotic base with everted edges. Which pairing is correct?", "opts": ["Both are keratoacanthoma", "Both are basal cell carcinoma", "Both are melanoma", "The clean base with shiny border is squamous cell carcinoma; the dirty base with everted edge is basal cell carcinoma", "Clean base with shiny border is basal cell carcinoma; dirty base with everted edge is squamous cell carcinoma"], "ans": 4, "interp": "", "why": "ลายมือ p73: SCC = base สกปรก · BCC = ขอบมัน · p35 SCC everted edge necrotic base", "wrong": {"A": "ไม่ใช่", "B": "ไม่ใช่", "C": "ไม่ใช่", "D": "สลับ"}, "summary": ["BCC ขอบมัน พื้นสะอาด · SCC ขอบ everted พื้นสกปรก"], "kimg": ["l22_p35", "l22_p37", "l22_p41", "l22_p42", "l22_p73"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 35, 37, 41, 42, 73 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 57, "notes": "p36: <b>Histologic types of squamous cell carcinoma — Well · Moderate · Poor-differentiated</b> · ลายมือ: <span class=\"hw\">↓ poor prognosis</span>", "stem": "Biopsies from two patients with cutaneous squamous cell carcinoma show a well-differentiated tumor in a 65-year-old man and a poorly differentiated tumor in a 66-year-old man. Which statement is correct?", "opts": ["Differentiation grading applies only to basal cell carcinoma, not to this tumor", "The poorly differentiated tumor carries the worse prognosis", "Poor differentiation means a benign lesion", "The well-differentiated tumor is more aggressive", "Both have the same prognosis"], "ans": 1, "interp": "", "why": "p36: histologic types — well, moderate, poor-differentiated (ลายมือ ↓ poor prognosis)", "wrong": {"A": "ไม่ใช่", "C": "ไม่ใช่", "D": "ตรงข้าม", "E": "ไม่ใช่"}, "summary": ["Poor differentiation → prognosis แย่"], "kimg": ["l22_p36"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 36 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 58, "notes": "p39 ลายมือ: <b>“squamous CA เป็นริมฝีปากล่าง &gt; บน”</b> · p38: <b>lower lips → squamous cell carcinoma มากกว่า ∵ เจอ irritation e.g. บุหรี่, หมาก</b>", "stem": "A 68-year-old man who has smoked for 50 years has a fungating ulcerated tumor of the lower lip. What is the most likely diagnosis?", "opts": ["Squamous cell carcinoma", "Venous malformation", "Keratoacanthoma of the upper lip", "Seborrheic keratosis", "Basal cell carcinoma"], "ans": 0, "interp": "", "why": "ลายมือ p38–39: lower lip → SCC มากกว่า ∵ irritation e.g. บุหรี่, หมาก · squamous CA เป็นริมฝีปากล่าง > บน", "wrong": {"B": "ไม่ใช่", "C": "ผิดตำแหน่ง", "D": "ไม่ใช่", "E": "ริมฝีปากบน"}, "summary": ["ริมฝีปากล่าง + บุหรี่/หมาก → SCC"], "kimg": ["l22_p38", "l22_p39", "l22_p40"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 38, 39, 40 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 59, "notes": "p40 ลายมือ: <b>“หนองดูสกปรก (necrotic tissue)”</b> · p38 ลายมือ: <b>“lower lips → squamous cell carcinoma มากกว่า ∵ เจอ irritation e.g. บุหรี่, หมาก”</b>", "stem": "A 75-year-old woman who has chewed betel for decades has a large, foul-smelling necrotic mass replacing most of the lower lip. Which statement is correct?", "opts": ["Sun exposure is the only risk factor for lip cancer, so betel chewing is irrelevant", "This is a typical basal cell carcinoma site", "The necrotic tissue indicates melanoma", "Chronic irritation from betel chewing predisposes to squamous cell carcinoma", "This lesion is a benign keratoacanthoma"], "ans": 3, "interp": "", "why": "ลายมือ p38/p40: lower lip SCC ∵ irritation (หมาก บุหรี่) · หนองดูสกปรก (necrotic tissue)", "wrong": {"A": "ไม่ใช่", "B": "ริมฝีปากล่าง = SCC", "C": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["หมาก → SCC ริมฝีปากล่าง"], "kimg": ["l22_p38", "l22_p39", "l22_p40"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 38, 39, 40 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 60, "notes": "p45 ลายมือ: <b>“squamous cell (more aggressive) = ขอ margin 1 cm · e.g. lesion ø 2 cm = ต้องผ่า 2 + 1 + 1 = 4 cm”</b>", "stem": "A 70-year-old man has a 2-cm squamous cell carcinoma on the forearm. Using the margin of 1 cm on each side, how wide will the excision be?", "opts": ["6 cm", "2.5 cm", "3 cm", "2 cm", "4 cm"], "ans": 4, "interp": "", "why": "ลายมือ p45: squamous cell (more aggressive) = ขอ margin 1 cm · e.g. lesion ø 2 cm = ต้องผ่า 2 + 1 + 1 = 4 cm", "wrong": {"A": "ใช้ 2 cm", "B": "ใช้ 0.25", "C": "margin ข้างเดียว", "D": "ไม่มี margin"}, "summary": ["SCC: lesion + 1 cm ทั้งสองข้าง"], "kimg": ["l22_p43", "l22_p45"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 43, 45 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 61, "notes": "p45 ลายมือ: <b>“basal cell (less aggressive) = ขอ margin 0.5 cm”</b> · p43: <b>margin 0.5 cm</b>", "stem": "A 65-year-old woman has a 1-cm nodular basal cell carcinoma on the back. Using the margins described for basal cell carcinoma, what is the total diameter of the excision?", "opts": ["3 cm", "4 cm", "2 cm", "1.5 cm", "1 cm"], "ans": 2, "interp": "", "why": "ลายมือ p43/p45: BCC (less aggressive) = ขอ margin 0.5 cm → 1 + 0.5 + 0.5 = 2 cm", "wrong": {"A": "ใช้ 1 cm (SCC)", "B": "ผิด", "D": "margin ข้างเดียว", "E": "ไม่มี margin"}, "summary": ["BCC margin 0.5 cm"], "kimg": ["l22_p43", "l22_p45"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 43, 45 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "trap": "ใช้ margin ของ SCC แทน BCC"}, {"n": 62, "notes": "p45 ลายมือ: <b>basal cell (less aggressive) = 0.5 cm · squamous cell (more aggressive) = 1 cm</b>", "stem": "A 72-year-old man has a 1.5-cm squamous cell carcinoma and a 1.5-cm basal cell carcinoma on the trunk, both low risk. Why is a wider margin used for the squamous cell carcinoma?", "opts": ["Basal cell carcinoma is benign", "Margins are the same for both", "Basal cell carcinoma metastasizes more often, so it needs the narrower margin", "Squamous cell carcinoma is more aggressive than basal cell carcinoma", "Squamous cell carcinoma is always larger"], "ans": 3, "interp": "", "why": "ลายมือ p45: basal cell (less aggressive) 0.5 cm · squamous cell (more aggressive) 1 cm (📘 NCCN low-risk BCC 4 mm, SCC 4–6 mm)", "wrong": {"A": "BCC เป็นมะเร็ง", "B": "ไม่เท่า", "C": "ตรงข้าม", "E": "ไม่ใช่"}, "summary": ["SCC aggressive กว่า → margin กว้างกว่า"], "kimg": ["l22_p43", "l22_p45"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 43, 45 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 63, "notes": "p44 ลายมือ: <b>“= skin cancer on chronic ulcer e.g. burn, chronic venous ulcer · ส่วนใหญ่เป็น squamous CA”</b>", "stem": "A 60-year-old man has a slowly enlarging, hard-edged ulcer arising within a scar from a burn he sustained 35 years ago. What is the most likely diagnosis?", "opts": ["Keloid", "Hypertrophic scar", "Marjolin's ulcer", "Venous ulcer", "Pressure injury"], "ans": 2, "interp": "", "why": "ลายมือ p44: Marjolin's ulcer = skin cancer on chronic ulcer e.g. burn, chronic venous ulcer · ส่วนใหญ่เป็น squamous CA", "wrong": {"A": "ไม่เป็นแผล", "B": "ไม่เป็นแผล", "D": "ไม่ได้อยู่บน burn scar", "E": "ไม่ใช่ตำแหน่ง"}, "summary": ["Burn scar + แผลใหม่ → Marjolin (SCC)"], "kimg": ["l22_p44"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 44 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 64, "notes": "p44: <b>Longstanding venous hypertension cause Majorlin's ulcer</b> · ลายมือ: <span class=\"hw\">ต้อง bx → tx by wide excision</span>", "stem": "A 70-year-old woman has had a venous leg ulcer for 20 years. Recently the edge has become raised and it bleeds easily. What is the appropriate next step?", "opts": ["Biopsy of the ulcer, followed by wide excision if malignant", "Skin graft without biopsy", "Topical antibiotics for 3 months", "Varicose vein stripping only", "Compression bandaging only, since the ulcer is venous in origin"], "ans": 0, "interp": "", "why": "p44: longstanding venous hypertension cause Marjolin's ulcer · ลายมือ ต้อง bx → tx by wide excision", "wrong": {"B": "ต้อง dx ก่อน", "C": "ไม่ใช่", "D": "ไม่พอ", "E": "ไม่พอ"}, "summary": ["แผลเรื้อรังเปลี่ยนลักษณะ → bx → wide excision"], "kimg": ["l22_p44"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 44 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "img": ["l22_p44"]}, {"n": 65, "notes": "p47: <b>Wide resection is not always possible, esp. Head and neck or facial area due to functional and aesthetic results · To control excised margin &gt;&gt;&gt; Mohs micrographic microsurgery was developed</b>", "stem": "A 65-year-old woman has a thick tumor on the nasal ala. Wide excision with standard margins would destroy much of the nose. Which approach best controls the margin while sparing tissue?", "opts": ["Observation", "Radical excision of the whole nose", "Mohs micrographic surgery", "Incision and drainage", "Cryotherapy without histology"], "ans": 2, "interp": "", "why": "p47: wide resection not always possible, esp. head and neck or facial area due to functional and aesthetic results · to control excised margin → Mohs micrographic surgery was developed", "wrong": {"A": "ไม่ใช่", "B": "เสียรูป", "D": "ไม่ใช่", "E": "ไม่ควบคุม margin"}, "summary": ["Head-neck → Mohs"], "kimg": ["l22_p47"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 47 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 66, "notes": "p47 ลายมือ: <b>“ยิ่งลึก → ยิ่งต้องตัดกว้าง” · “→ ขึ้นกับ ค.ลึกของ lesion · ยิ่งลึก = ลงล่างมากกว่าออกข้าง”</b>", "stem": "A 60-year-old man has two skin cancers of the same width; one invades 1 mm and the other 5 mm deep. How should the surgical margin differ?", "opts": ["Both need identical margins", "Neither needs a margin", "The shallower tumor needs a wider margin because it spreads laterally", "Depth does not affect margins", "The deeper tumor needs a wider and deeper margin"], "ans": 4, "interp": "", "why": "p47: optimal surgical margin is not known (ลายมือ → ขึ้นกับความลึกของ lesion · ยิ่งลึก = ลงล่างมากกว่าออกข้าง) · ยิ่งลึก → ยิ่งต้องตัดกว้าง", "wrong": {"A": "ไม่ใช่", "B": "ผิด", "C": "ตรงข้าม", "D": "ผิด"}, "summary": ["ยิ่งลึก → margin กว้างขึ้น"], "kimg": ["l22_p47"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 47 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 67, "notes": "p46: <b>Malignant melanoma</b> · ลายมือ: <span class=\"hw\">แตกเป็นแผล, สีไม่สม่ำเสมอ</span>", "stem": "A 50-year-old man has a dark lesion on the scalp that has recently ulcerated and shows uneven black, brown and red color. Which diagnosis is most concerning?", "opts": ["Seborrheic keratosis", "Malignant melanoma", "Epidermal cyst", "Lipoma", "Capillary malformation"], "ans": 1, "interp": "", "why": "ลายมือ p46: malignant melanoma — แตกเป็นแผล, สีไม่สม่ำเสมอ", "wrong": {"A": "ไม่แตก", "C": "ใต้ผิว", "D": "ใต้ผิว", "E": "ไม่ใช่"}, "summary": ["Melanoma: แตกเป็นแผล สีไม่สม่ำเสมอ"], "kimg": ["l22_p46", "l22_p73"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 46, 73 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "img": ["l22_p46"]}, {"n": 68, "notes": "p46: <b>Malignant melanoma</b>", "stem": "A 58-year-old Thai man has a black, irregular patch on the sole of his foot that has enlarged over a year. Which subtype of melanoma is most common in Asian patients at this site?", "opts": ["Desmoplastic melanoma", "Acral lentiginous melanoma", "Superficial spreading melanoma", "Amelanotic melanoma", "Lentigo maligna melanoma"], "ans": 1, "interp": "", "why": "p46 melanoma · 📖 ฝ่ามือ ฝ่าเท้า ใต้เล็บ = acral lentiginous พบบ่อยสุดในเอเชีย/คนไทย · นอกสไลด์: Sabiston: acral lentiginous melanoma common in Asians", "wrong": {"A": "พบน้อย", "C": "คนผิวขาว", "D": "ไม่มีสี", "E": "หน้าผู้สูงอายุ"}, "summary": ["Asian → acral lentiginous"], "kimg": ["l22_p46", "l22_p73"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 46, 73 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์ · นอกสไลด์"}, {"n": 69, "notes": "p49: <b>ABCD criteria by The American Cancer Society — Asymmetry in shape · Border irregularities · Color heterogeneity · Diameter greater than 6 mm</b>", "stem": "A 42-year-old woman has a mole whose two halves do not match, with notched edges, several shades of brown and black, and a diameter of 8 mm. Which criteria does this lesion fulfill?", "opts": ["Only the color criterion", "All four ABCD criteria for melanoma", "None, because it is smaller than 10 mm", "Only the diameter criterion", "Criteria for seborrheic keratosis"], "ans": 1, "interp": "", "why": "p49–50: ABCD criteria — asymmetry in shape · border irregularities · color heterogeneity · diameter greater than 6 mm", "wrong": {"A": "ไม่ครบ", "C": "เกณฑ์ > 6 mm", "D": "ไม่ครบ", "E": "ไม่ใช่"}, "summary": ["ABCD: Asymmetry Border Color Diameter > 6 mm"], "kimg": ["l22_p49", "l22_p50"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 49, 50 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 70, "notes": "p49: <b>Diameter greater than 6 mm</b> · p50: <b>if the mole's diameter is larger than a pencil's eraser</b>", "stem": "A 35-year-old man has a round, uniformly brown, sharply bordered 4-mm mole that has not changed. Which statement is correct?", "opts": ["It does not meet ABCD criteria for melanoma", "It must be excised widely", "It meets the diameter criterion because it is larger than 3 mm", "It meets the color criterion", "It is a seborrheic keratosis"], "ans": 0, "interp": "", "why": "p49–50: diameter > 6 mm (ใหญ่กว่ายางลบดินสอ) · symmetric, border เรียบ, สีเดียว = ไม่เข้า ABCD", "wrong": {"B": "ไม่จำเป็น", "C": "4 mm < 6 mm", "D": "สีเดียว", "E": "ไม่ใช่"}, "summary": ["D > 6 mm"], "kimg": ["l22_p49", "l22_p50"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 49, 50 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 71, "notes": "p48 รูป: <b>Granular cell layer ↔ Deepest invading malignant melanocyte</b> · p51 ลายมือ: <span class=\"hw\">Breslow's = บอก ค.ลึกเป็น mm · Clark's = บอกว่าอยู่ layer ไหน</span>", "stem": "A 50-year-old woman's melanoma pathology report states a Breslow thickness of 1.6 mm. How is this measurement obtained?", "opts": ["By identifying the anatomical skin layer that the tumor has reached, from I to V", "From the stratum corneum to the subcutaneous fat", "From the lesion edge to the excision margin", "From the granular cell layer to the deepest invading melanoma cell", "By counting mitoses per square millimeter"], "ans": 3, "interp": "", "why": "p48/p52: Breslow depth = วัดเป็น mm จาก granular cell layer ถึง deepest invading malignant melanocyte · Clark = บอกว่าอยู่ layer ไหน", "wrong": {"A": "= Clark level", "B": "ไม่ใช่", "C": "= margin", "E": "= mitotic rate"}, "summary": ["Breslow = mm · Clark = layer"], "kimg": ["l22_p48", "l22_p52"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 48, 52 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 72, "notes": "p54: <b>Surgery : wide excision, lymph node dissection</b>", "stem": "A 55-year-old man has a 2.5-mm thick melanoma on the back with a palpable axillary lymph node. Which surgical treatment is described for melanoma?", "opts": ["Shave excision only", "Mohs surgery without nodal treatment", "Topical imiquimod", "Wide excision with lymph node dissection", "Cryotherapy"], "ans": 3, "interp": "", "why": "p54: treatment — surgery: wide excision, lymph node dissection · chemo · RT · immunotherapy (ลายมือ พวก IFNs) · novel (melanoma vaccine)", "wrong": {"A": "ไม่พอ", "B": "ไม่พอ", "C": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["Melanoma: wide excision ± LN dissection"], "kimg": ["l22_p54"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 54 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 73, "notes": "p54: <b>Immunotherapy</b> <span class=\"hw\">→ พวก IFNs</span> · <b>Novel treatment</b> <span class=\"hw\">กำลังจะมี melanoma vaccine</span>", "stem": "A 60-year-old woman has metastatic melanoma with a BRAF V600E mutation. Which systemic therapy class is now the mainstay, compared with interferon used in the past?", "opts": ["Radiotherapy alone", "Immune checkpoint inhibitors or BRAF/MEK inhibitors", "Oral antifungals", "Chemotherapy with methotrexate alone", "High-dose interferon alone, as in the classic teaching"], "ans": 1, "interp": "", "why": "p54: immunotherapy (ลายมือ พวก IFNs) · 📘 NCCN 2026: anti-PD-1 ± anti-CTLA-4 และ BRAF/MEK inhibitor (IFN แทบไม่ใช้แล้ว) · นอกสไลด์: NCCN Melanoma v2.2026", "wrong": {"A": "ไม่พอ", "C": "ไม่ใช่", "D": "ไม่ใช่", "E": "เลิกใช้"}, "summary": ["Melanoma ปัจจุบัน: checkpoint/BRAF-MEK"], "kimg": ["l22_p54"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 54 · ไม่มีสัญลักษณ์คณะ · ลายมือ · นอกสไลด์", "trap": "สไลด์บอก IFN แต่ปัจจุบันไม่ใช่"}, {"n": 74, "notes": "p55: <b>Surgical treatment of primary melanoma — In situ 0.5 · &lt;1 mm 1.0 · 1-2 mm 1.0-2.0 · 2-4 mm 2.0 · &gt;4 mm 2.0-3.0</b>", "stem": "A 48-year-old woman has a 0.6-mm thick melanoma of the arm. What clinical excision margin is recommended?", "opts": ["3 cm", "0.2 cm", "5 cm", "1 cm", "0.5 cm"], "ans": 3, "interp": "", "why": "p55: < 1 mm → 1.0 cm (in situ 0.5 · 1–2 mm 1–2 · 2–4 mm 2 · > 4 mm 2–3) · 📘 NCCN ≤ 1 mm = 1 cm", "wrong": {"A": "> 4 mm (สไลด์)", "B": "น้อยไป", "C": "เกิน", "E": "= in situ"}, "summary": ["Melanoma < 1 mm → 1 cm"], "kimg": ["l22_p55"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 55 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 75, "notes": "p56 ลายมือ: <b>“= ค่อย ๆ ตัดทีละ mm · กรณีอยู่ใกล้ organ สำคัญ”</b> · p57 ลายมือ: <b>“ตัดทีละ mm แล้วมาเช็คว่ายังมี lesion อยู่ไหม → ตอนตัด = dermatopathologist นั่งดูเลย · เอาไปทำ frozen ดู → ถ้า margin ไม่ free → ตัดต่อ · ตัดเพิ่มแค่ฝั่งที่ยัง positive จนกว่าจะ free → reconstruct + ปิดแผล”</b>", "stem": "A 70-year-old man has a basal cell carcinoma near the lower eyelid. The surgeon removes thin layers one at a time, examines frozen sections of all margins with a map, and excises further only where tumor remains. What is this technique?", "opts": ["Shave biopsy", "Curettage and electrodesiccation", "Wide local excision", "Mohs micrographic surgery", "Sentinel lymph node biopsy"], "ans": 3, "interp": "", "why": "ลายมือ p56–57: Mohs = ค่อย ๆ ตัดทีละ mm · ตอนตัด dermatopathologist นั่งดู · frozen → ถ้า margin ไม่ free → ตัดต่อ · ตัดเพิ่มแค่ฝั่งที่ยัง positive จนกว่าจะ free → reconstruct", "wrong": {"A": "ไม่ใช่", "B": "ไม่ตรวจขอบ", "C": "ไม่ตรวจทีละชั้น", "E": "ไม่ใช่"}, "summary": ["Mohs = ตัดทีละชั้น + frozen + mapping"], "kimg": ["l22_p56", "l22_p57"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 56, 57 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 76, "notes": "p56 ลายมือ: <b>“กรณีอยู่ใกล้ organ สำคัญ”</b> · p57: <b>“ใช้กับบนหน้า → ไม่อยากตัดเยอะ”</b>", "stem": "A 66-year-old woman has a recurrent basal cell carcinoma at the medial canthus close to the lacrimal duct. Which treatment is most appropriate?", "opts": ["Observation", "Wide excision with 2-cm margins", "Mohs micrographic surgery", "Radiotherapy to the whole face", "Topical 5-fluorouracil"], "ans": 2, "interp": "", "why": "ลายมือ p56: Mohs กรณีอยู่ใกล้ organ สำคัญ · p57 ใช้กับบนหน้า → ไม่อยากตัดเยอะ (📘 recurrent/H-zone = high-risk → Mohs)", "wrong": {"A": "ไม่ใช่", "B": "เสียอวัยวะ", "D": "ไม่ใช่", "E": "ไม่ใช่สำหรับ recurrent"}, "summary": ["ใกล้อวัยวะสำคัญ/recurrent → Mohs"], "kimg": ["l22_p56", "l22_p57"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 56, 57 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 77, "notes": "p58: <b>Advantage: High cure rates · Decrease morbidity · Significant tissue conservation · Disadvantage: Time, Cost · Inconvenience to patient · Require specialist</b>", "stem": "A 75-year-old man with a facial basal cell carcinoma is offered Mohs surgery. Which is a disadvantage he should be told about?", "opts": ["It cannot be used on the face", "It increases morbidity compared with standard excision", "It is time-consuming, costly and requires a specialist", "It has a low cure rate", "It removes more normal tissue than wide excision"], "ans": 2, "interp": "", "why": "p58: disadvantage — time, cost · inconvenience to patient · require specialist · advantage — high cure rates, decrease morbidity, tissue conservation", "wrong": {"A": "ใช้บนหน้าดี", "B": "ลด morbidity", "D": "cure สูง", "E": "ตรงข้าม"}, "summary": ["Mohs: + cure สูง เก็บเนื้อ · − เวลา เงิน specialist"], "kimg": ["l22_p58"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 58 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 78, "notes": "p58 ลายมือ: <b>Decrease morbidity “∵ สูญเสีย tissue น้อย”</b>", "stem": "A 68-year-old woman asks why Mohs surgery causes less morbidity than standard excision for her nasal tumor. What is the best explanation?", "opts": ["It avoids any need for local anesthesia", "It is performed without histology", "It always avoids reconstruction", "Less normal tissue is removed because margins are checked layer by layer", "It removes and treats regional lymph node metastasis during the same operation"], "ans": 3, "interp": "", "why": "ลายมือ p58: decrease morbidity ∵ สูญเสีย tissue น้อย (tissue conservation)", "wrong": {"A": "ใช้ LA", "B": "ตรวจ histology", "C": "อาจต้อง reconstruct", "E": "ไม่ใช่"}, "summary": ["Mohs ↓ morbidity ∵ เสีย tissue น้อย"], "kimg": ["l22_p58"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 58 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 79, "notes": "p59 ลายมือ: <b>“ถ้า P เกิน 2 เท่าของ capillary arterial end (32 mmHg) [65 mmHg] 2 ชม. → irreversible tissue damage ∴ พลิกตัวทุก 2 ชม.”</b>", "stem": "A 70-year-old man after stroke lies motionless on his back. Pressure over the sacrum is about 70 mm Hg. Approximately how long before irreversible tissue damage occurs, and what is the preventive measure?", "opts": ["About 24 hours; so turning him once daily is sufficient", "About 1 week; no turning needed", "Damage never occurs below 100 mm Hg, so no action is needed", "About 10 minutes; keep him sitting", "About 2 hours; turn him every 2 hours"], "ans": 4, "interp": "", "why": "ลายมือ p59: ถ้า P เกิน 2 เท่าของ capillary arterial end (32 mmHg) [~65 mmHg] 2 ชม. → irreversible tissue damage ∴ พลิกตัวทุก 2 ชม.", "wrong": {"A": "นานไป", "B": "นานไป", "C": "ผิด", "D": "ไม่ใช่ (นั่งกด ischium)"}, "summary": ["> ~65 mmHg 2 ชม. → พลิกตัวทุก 2 ชม."], "kimg": ["l22_p59"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 59 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 80, "notes": "p59: <b>Pressure → decrease cutaneous vascular flow → local tissue ischemia</b>", "stem": "A 25-year-old paraplegic man develops a skin ulcer over a bony prominence. Which mechanism initiates this injury?", "opts": ["Pressure reduces cutaneous blood flow, causing local tissue ischemia", "Autoimmune vasculitis", "Venous hypertension", "Arterial embolism", "Bacterial infection of the skin is the primary cause of the ulcer"], "ans": 0, "interp": "", "why": "p59: pressure → decrease cutaneous vascular flow → local tissue ischemia", "wrong": {"B": "ไม่ใช่", "C": "ไม่ใช่", "D": "ไม่ใช่", "E": "ตามมาทีหลัง"}, "summary": ["Pressure → ischemia"], "kimg": ["l22_p59"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 59 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 81, "notes": "p59: <b>Sitting position: ischial tuberosities · Supine position: sacral area</b>", "stem": "A 30-year-old wheelchair user with spinal cord injury sits for many hours each day. Where is a pressure injury most likely to develop?", "opts": ["Over the heel", "Over the greater trochanter", "Over the occiput", "Over the sacrum", "Over the ischial tuberosities"], "ans": 4, "interp": "", "why": "p59: sitting position → ischial tuberosities · supine → sacral area", "wrong": {"A": "นอนหงาย", "B": "= ตะแคง", "C": "เด็ก/นอนหงาย", "D": "= supine"}, "summary": ["นั่ง = ischial · นอนหงาย = sacrum"], "kimg": ["l22_p59"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 59 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 82, "notes": "p59 ลายมือ: <b>“ตะแคง : greater trochanter, lat. malleolus, ใบหู”</b>", "stem": "An 80-year-old bedridden woman is always kept lying on her right side. Which sites are at highest risk of pressure injury?", "opts": ["Greater trochanter, lateral malleolus and ear", "Sacrum only", "Ischial tuberosities, from prolonged sitting in bed", "Scapulae", "Occiput, scapulae and heels"], "ans": 0, "interp": "", "why": "ลายมือ p59: ตะแคง : greater trochanter, lat. malleolus, ใบหู", "wrong": {"B": "= นอนหงาย", "C": "= นั่ง", "D": "นอนหงาย", "E": "นอนหงาย"}, "summary": ["ตะแคง → trochanter, malleolus, ใบหู"], "kimg": ["l22_p59"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 59 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 83, "notes": "p59: <b>Treatment: relief of pressure, wound care, systemic enhancement</b>", "stem": "A 76-year-old woman with dementia and malnutrition has a deep sacral pressure injury. Which combination of treatments is required?", "opts": ["Relief of pressure, wound care and systemic enhancement such as nutrition", "Topical antibiotics alone", "Immediate skin grafting of the wound without changing her position", "Bed rest on the back to protect the wound", "Systemic steroids"], "ans": 0, "interp": "", "why": "p59: treatment — relief of pressure, wound care, systemic enhancement", "wrong": {"B": "ไม่พอ", "C": "ไม่ off-load แล้ว graft ไม่ติด", "D": "กดเพิ่ม", "E": "แย่ลง"}, "summary": ["Off-load + wound care + systemic"], "kimg": ["l22_p59"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 59 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 84, "notes": "p59 ลายมือ: <b>“best = prevent”</b> · <b>“∴ พลิกตัวทุก 2 ชม.”</b>", "stem": "A 55-year-old man is admitted to the ICU after a stroke. What is the best strategy regarding pressure injuries?", "opts": ["Keep him sitting upright all day", "Give prophylactic antibiotics", "Restrict nutrition to reduce weight", "Prevention by regular repositioning and pressure redistribution", "Wait for a pressure injury to appear and then start dressing it"], "ans": 3, "interp": "", "why": "ลายมือ p59: Treatment — best = prevent (พลิกตัวทุก 2 ชม.)", "wrong": {"A": "กด ischium", "B": "ไม่ใช่", "C": "แย่ลง", "E": "ผิด"}, "summary": ["Best treatment = prevention"], "kimg": ["l22_p59"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 59 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 85, "notes": "p60: <b>Stage I — Skin intact but redden for more than 1 hour</b>", "stem": "An 82-year-old bedbound man has an area over the sacrum with intact skin that remains red and does not blanch for more than an hour after repositioning. What stage is this?", "opts": ["Stage IV", "Stage I", "Stage III", "Unstageable", "Stage II"], "ans": 1, "interp": "", "why": "p60: stage I — skin intact but redden for more than 1 hour", "wrong": {"A": "ถึงกระดูก", "C": "ลึกถึง subcut", "D": "มี slough ปิด", "E": "มี blister/แผล"}, "summary": ["Stage I = ผิวไม่แตก แดงไม่จาง"], "kimg": ["l22_p60"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 60 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 86, "notes": "p60: <b>Stage IV — Involvement of bone or joint</b>", "stem": "A 70-year-old woman has a sacral pressure injury in which bone is exposed at the base. What stage is this?", "opts": ["Stage II", "Deep tissue injury", "Stage I", "Stage IV", "Stage III"], "ans": 3, "interp": "", "why": "p60: stage IV — involvement of bone or joint", "wrong": {"A": "blister", "B": "ผิวไม่แตกสีม่วง", "C": "ผิวไม่แตก", "E": "subcut (ไม่ถึงกระดูก)"}, "summary": ["Stage IV = bone/joint"], "kimg": ["l22_p60"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 60 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 87, "notes": "p60: <b>Stage II — Blister or other break in dermis</b>", "stem": "A 67-year-old man has a heel pressure injury with a ruptured blister exposing pink dermis, without visible fat. What stage is this?", "opts": ["Stage II", "Unstageable", "Stage III", "Stage I", "Stage IV"], "ans": 0, "interp": "", "why": "p60: stage II — blister or other break in dermis", "wrong": {"B": "มองเห็นพื้นแผล", "C": "ถึง subcut/เห็นไขมัน", "D": "ผิวไม่แตก", "E": "ถึงกระดูก"}, "summary": ["Stage II = blister/แผลถึง dermis"], "kimg": ["l22_p60"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 60 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 88, "notes": "p61: <b>Bacterial infections — Staphylococcus aureus · Streptococcus pyogenes [beta-haemolytic Streptococcus Lancefield group A]</b>", "stem": "A 30-year-old man has a skin infection caused by beta-hemolytic Streptococcus Lancefield group A. Which organism is this?", "opts": ["Herpes simplex virus", "Staphylococcus aureus", "Human papillomavirus", "Pox virus", "Streptococcus pyogenes"], "ans": 4, "interp": "", "why": "p61: bacterial infections — Staphylococcus aureus · Streptococcus pyogenes [beta-haemolytic Streptococcus Lancefield group A] · viral: HPV, pox, herpes", "wrong": {"A": "virus", "B": "ไม่ใช่ strep", "C": "virus", "D": "virus"}, "summary": ["GAS = Strep pyogenes"], "kimg": ["l22_p61"], "tags": ["Plastic", "Surgical infection"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 61 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 89, "notes": "p62: <b>Folliculitis</b> · ลายมือ: <span class=\"hw\">e.g. ที่หนวด, รักแร้ · เป็นน้อย ๆ อาจจะหายเอง · หลายเม็ด → oral dicloxacillin</span>", "stem": "A 25-year-old man has a few small pustules centered on hair follicles in the beard area, without fever. What is the most appropriate management?", "opts": ["Observation and hygiene because mild folliculitis may resolve spontaneously", "Incision and drainage of each pustule under local anesthesia", "Intravenous vancomycin", "Wide surgical debridement", "Radiotherapy"], "ans": 0, "interp": "", "why": "ลายมือ p62: folliculitis e.g. ที่หนวด, รักแร้ · เป็นน้อย ๆ อาจจะหายเอง · หลายเม็ด → oral dicloxacillin", "wrong": {"B": "ไม่ใช่ฝี", "C": "เกิน", "D": "เกิน", "E": "ไม่ใช่"}, "summary": ["Folliculitis น้อย → หายเอง"], "kimg": ["l22_p62", "l22_p63", "l22_p64"], "tags": ["Plastic", "Surgical infection"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 62, 63, 64 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 90, "notes": "p62 ลายมือ: <b>“หลายเม็ด → oral dicloxacillin”</b>", "stem": "A 30-year-old woman has many follicular pustules on both thighs after shaving. What is the appropriate antibiotic?", "opts": ["Intravenous ceftazidime", "Oral acyclovir", "Topical antifungal", "Oral metronidazole", "Oral dicloxacillin"], "ans": 4, "interp": "", "why": "ลายมือ p62: หลายเม็ด → oral dicloxacillin (ครอบคลุม S. aureus)", "wrong": {"A": "เกิน", "B": "virus", "C": "ไม่ใช่ fungus", "D": "anaerobe"}, "summary": ["Folliculitis หลายเม็ด → dicloxacillin"], "kimg": ["l22_p62", "l22_p63", "l22_p64"], "tags": ["Plastic", "Surgical infection"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 62, 63, 64 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 91, "notes": "p65: <b>Furuncle</b> <span class=\"hw\">: abscess → I&amp;D</span>", "stem": "A 22-year-old man has a painful, fluctuant 2-cm red nodule with a central pustule in the axilla. What is the treatment?", "opts": ["Observation", "Oral antibiotics alone", "Topical steroid", "Incision and drainage", "Wide excision of the axillary skin"], "ans": 3, "interp": "", "why": "ลายมือ p65: furuncle : abscess → I&D", "wrong": {"A": "ไม่ใช่", "B": "ไม่พอสำหรับหนอง", "C": "ไม่ใช่", "E": "เกิน"}, "summary": ["Furuncle (abscess) → I&D"], "kimg": ["l22_p65", "l22_p66"], "tags": ["Plastic", "Surgical infection"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 65, 66 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "img": ["l22_p65"]}, {"n": 92, "notes": "p68: <b>Boil (furuncle) with abscess · Carbuncle (cluster of boils)</b>", "stem": "A 35-year-old woman has a single boil on the leg arising from one hair follicle. How does this lesion differ from a carbuncle?", "opts": ["A carbuncle is a viral infection", "A furuncle is a single follicular abscess, whereas a carbuncle is several interconnected abscesses", "They are identical", "A furuncle involves many follicles", "A furuncle is always deeper than a carbuncle and needs wider debridement"], "ans": 1, "interp": "", "why": "p65–68: furuncle = boil with abscess (1 follicle) · carbuncle = cluster of boils (หลาย pockets)", "wrong": {"A": "ไม่ใช่", "C": "ไม่ใช่", "D": "ตรงข้าม", "E": "ไม่ใช่"}, "summary": ["Furuncle 1 · carbuncle หลาย pocket"], "kimg": ["l22_p65", "l22_p66"], "tags": ["Plastic", "Surgical infection"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 65, 66 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 93, "notes": "p67 ลายมือ: <b>“= หลาย pockets ติดกัน → I&amp;D อาจไม่ครบทุก pockets → Debride skin เลย · หนองฝีฝักบัว”</b>", "stem": "A 60-year-old diabetic man has a large, indurated, painful lesion on the back of the neck with multiple draining sinus openings. What is the most appropriate surgical management?", "opts": ["Needle aspiration", "Observation", "Single small stab incision over the largest opening", "Debridement of the involved skin and pockets", "Topical antibiotic only"], "ans": 3, "interp": "", "why": "ลายมือ p67–68: carbuncles = หลาย pockets ติดกัน → I&D อาจไม่ครบทุก pockets → Debride skin เลย · มีหลายรูเปิด → ต้อง debride (หนองฝีฝักบัว)", "wrong": {"A": "ไม่พอ", "B": "ไม่ใช่", "C": "ระบายไม่หมด", "E": "ไม่พอ"}, "summary": ["Carbuncle → debride"], "kimg": ["l22_p67", "l22_p68"], "tags": ["Plastic", "Surgical infection"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 67, 68 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 94, "notes": "p68: <b>Carbuncle (cluster of boils)</b>", "stem": "A 55-year-old man has a cluster of interconnected boils on his upper back. Which term describes this lesion?", "opts": ["Cellulitis", "Carbuncle", "Epidermal cyst", "Folliculitis", "Furuncle"], "ans": 1, "interp": "", "why": "p67–68: carbuncle = cluster of boils (ลายมือ หนองฝีฝักบัว)", "wrong": {"A": "ไม่มีหนอง pocket", "C": "ไม่ใช่", "D": "ตุ่มเล็ก", "E": "ก้อนเดียว"}, "summary": ["Carbuncle = cluster of boils"], "kimg": ["l22_p67", "l22_p68"], "tags": ["Plastic", "Surgical infection"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 67, 68 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 95, "notes": "p69 ลายมือ: <b>“→ แผลอาจไม่ใหญ่ แต่มี sepsis · กิน fascia ได้ไกล” · “Tx : debride (กรีดแล้วเอานิ้วเซาะออก) → เอา skin ข้างบนทิ้งหมด → dressing จนเกิด granulation tissue → แปะ graft”</b>", "stem": "A 50-year-old diabetic man has severe leg pain, fever and hypotension. The skin shows a small dusky area with bullae, but pain far exceeds the visible findings. At surgery, the fascia separates easily with a finger. What is the diagnosis and treatment?", "opts": ["Furuncle requiring incision and drainage", "Deep vein thrombosis requiring heparin", "Cellulitis requiring oral antibiotics and leg elevation at home for a week", "Lymphedema requiring compression", "Necrotizing fasciitis requiring urgent radical debridement and broad-spectrum antibiotics"], "ans": 4, "interp": "", "why": "ลายมือ p69: แผลอาจไม่ใหญ่ แต่มี sepsis · กิน fascia ได้ไกล · Tx: debride (กรีดแล้วเอานิ้วเซาะออก) → เอา skin ข้างบนทิ้ง → dressing → graft · mixed organism", "wrong": {"A": "ไม่ใช่", "B": "ไม่ใช่", "C": "ไม่พอ", "D": "ไม่ใช่"}, "summary": ["NF: debride ด่วน + ATB กว้าง"], "kimg": ["l22_p69"], "tags": ["Plastic", "Surgical infection"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 69 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 96, "notes": "p69 ลายมือ: <b>“ถ้าเป็นที่ perineum = Fournier gangrene”</b>", "stem": "A 58-year-old diabetic man has rapidly spreading necrosis of the scrotal and perineal skin with sepsis. What is this condition called?", "opts": ["Pressure injury", "Marjolin's ulcer", "Fournier gangrene", "Carbuncle", "Hidradenitis suppurativa"], "ans": 2, "interp": "", "why": "ลายมือ p69: ถ้าเป็นที่ perineum = Fournier gangrene", "wrong": {"A": "ไม่ใช่", "B": "ไม่ใช่", "D": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["NF ที่ perineum = Fournier"], "kimg": ["l22_p69"], "tags": ["Plastic", "Surgical infection"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 69 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 97, "notes": "p69 ลายมือ: <b>“vss. เหนือ fascia พัง → perforator พัง → cut. ischemia → necrosis” · “ตัวส่ง vss มาเลี้ยง skin ข้างบน : ถ้าเจ๊ง = skin ข้างบนตายด้วย”</b>", "stem": "A 47-year-old man has necrotizing fasciitis of the leg with dusky, dying skin over the infected fascia. Why does the overlying skin become necrotic when the infection is centered on the fascia?", "opts": ["Antibiotics damage the skin", "The epidermis loses melanocytes", "Vessels running above the fascia and their perforators to the skin are destroyed", "Venous thrombosis of the deep leg veins causes the skin to die from congestion", "The skin is directly infected first"], "ans": 2, "interp": "", "why": "ลายมือ p69 (แดง): vss. เหนือ fascia พัง → perforator พัง → cut. ischemia → necrosis · ตัวส่ง vss มาเลี้ยง skin ข้างบน : ถ้าเจ๊ง = skin ข้างบนตายด้วย", "wrong": {"A": "ไม่ใช่", "B": "ไม่ใช่", "D": "ไม่ใช่", "E": "กลับลำดับ"}, "summary": ["Perforator thrombosis → skin necrosis"], "kimg": ["l22_p2", "l22_p69"], "tags": ["Plastic", "Surgical infection"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 2, 69 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 98, "notes": "p70 ลายมือ: <b>“neurofibroma — นุ่ม ๆ”</b>", "stem": "A 35-year-old woman has a soft, skin-colored papule on the trunk that invaginates into the skin when pressed. She has several similar lesions. What is the most likely diagnosis?", "opts": ["Basal cell carcinoma", "Seborrheic keratosis", "Lipoma", "Neurofibroma", "Keratoacanthoma"], "ans": 3, "interp": "", "why": "ลายมือ p70 (C): neurofibroma — นุ่ม ๆ (📖 buttonhole sign) · หลายก้อน → คิด NF1", "wrong": {"A": "ขอบมุก", "B": "stuck-on", "C": "ใต้ผิวโยกได้", "E": "มี keratin plug"}, "summary": ["Neurofibroma นุ่ม กดยุบ"], "kimg": ["l22_p70"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 70 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 99, "notes": "p70: <b>benign — A seborrheic keratosis · B nevus sebaceous of Jadassohn (เป็น premalignant → excision) · C neurofibroma · D keratoacanthoma</b>", "stem": "A 70-year-old man has four lesions photographed: a stuck-on brown plaque, a congenital yellow scalp plaque, a soft skin-colored papule, and a crater-like nodule with a keratin plug. Which one is premalignant?", "opts": ["The soft skin-colored papule", "The congenital yellow scalp plaque", "The crater-like nodule with a keratin plug", "None of them", "The stuck-on brown plaque"], "ans": 1, "interp": "", "why": "p70: A seborrheic keratosis (benign) · B nevus sebaceous (ลายมือ เป็น premalignant → excision) · C neurofibroma · D keratoacanthoma", "wrong": {"A": "= neurofibroma", "C": "= KA (รักษาแบบ SCC แต่จัดใน benign ของสไลด์)", "D": "ไม่ใช่", "E": "= SK"}, "summary": ["Nevus sebaceous = premalignant"], "kimg": ["l22_p70"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 70 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "img": ["l22_p70"]}, {"n": 100, "notes": "p72: <b>Diagnostic criteria (≥2 of the following) — Six or more café-au-lait macules over 5mm in greatest diameter in prepubertal individuals … · Freckling in the axillary or inguinal regions · A first-degree relative with NF1</b>", "stem": "A 10-year-old boy has seven café-au-lait macules larger than 5 mm and freckling in both axillae. His mother has multiple soft skin nodules. What is the diagnosis?", "opts": ["Neurofibromatosis type 1", "Neurofibromatosis type 2", "Tuberous sclerosis", "Xeroderma pigmentosum", "McCune–Albright syndrome"], "ans": 0, "interp": "", "why": "p72: NF1 diagnostic criteria ≥ 2: ≥ 6 café-au-lait > 5 mm (ก่อนวัยรุ่น) · axillary/inguinal freckling · first-degree relative with NF1", "wrong": {"B": "central (vestibular schwannoma)", "C": "ash-leaf, angiofibroma", "D": "ไม่ใช่", "E": "café-au-lait ขอบขรุขระ + fibrous dysplasia"}, "summary": ["NF1 ≥ 2 จาก 7 เกณฑ์"], "kimg": ["l22_p71", "l22_p72"], "tags": ["Plastic", "Pediatric surgery"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 71, 72 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 101, "notes": "p72: <b>Mode of inheritance? AD (50%) · De novo (50%) · NF1 gene on chromosome 17</b>", "stem": "A 25-year-old woman with neurofibromatosis type 1 asks about inheritance. Neither parent is affected. Which statement is correct?", "opts": ["It is autosomal recessive, with the responsible gene located on chromosome 22, so carriers are unaffected", "About half of cases arise de novo; the disease is autosomal dominant with the NF1 gene on chromosome 17", "It is never inherited", "It is caused by chromosome 13 deletion", "It is X-linked"], "ans": 1, "interp": "", "why": "p72: mode of inheritance — AD (50%) · de novo (50%) · NF1 gene on chromosome 17 (ลายมือ cf. type 2 = central, chr 22)", "wrong": {"A": "= NF2 chr 22 (AD)", "C": "ส่งต่อ AD", "D": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["NF1: AD, 50% de novo, chr 17"], "kimg": ["l22_p71", "l22_p72"], "tags": ["Plastic", "Pediatric surgery"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 71, 72 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 102, "notes": "p72: <b>What is 1st manifestation typically appears? — Café-au-lait macules · What is most common type of benign tumor in NF1? — Neurofibromas</b>", "stem": "A 3-year-old child is suspected of neurofibromatosis type 1. Which feature typically appears first?", "opts": ["Neurofibromas", "Optic glioma symptoms", "Café-au-lait macules", "Pseudarthrosis", "Lisch nodules"], "ans": 2, "interp": "", "why": "p72: What is 1st manifestation typically appears? — café-au-lait macules · most common benign tumor = neurofibromas", "wrong": {"A": "มาภายหลัง (วัยรุ่น)", "B": "ไม่ใช่ตัวแรก", "D": "ไม่ใช่", "E": "มาภายหลัง"}, "summary": ["NF1 แรก = café-au-lait"], "kimg": ["l22_p71", "l22_p72"], "tags": ["Plastic", "Pediatric surgery"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 71, 72 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 103, "notes": "p73 ลายมือ: <b>“malignant — ถ้าสงสัย skin CA → ทำ incisional biopsy ส่งก่อน”</b>", "stem": "A 72-year-old man has a suspicious 3-cm ulcerated tumor on the cheek. Before definitive surgery, what should be done first?", "opts": ["Observation for 3 months", "Topical antibiotic", "Radiotherapy", "Incisional biopsy to confirm the diagnosis", "Wide excision with 2-cm margins without diagnosis"], "ans": 3, "interp": "", "why": "ลายมือ p73: malignant — ถ้าสงสัย skin CA → ทำ incisional biopsy ส่งก่อน (ขีดคำ excisional ออก) · 📘 แต่สงสัย melanoma → excisional bx 1–3 mm ดีที่สุด", "wrong": {"A": "ช้า", "B": "ไม่ใช่", "C": "ไม่ใช่", "E": "ยังไม่รู้ dx"}, "summary": ["สงสัย skin CA ก้อนใหญ่ → incisional bx ก่อน"], "kimg": ["l22_p73"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 73 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 104, "notes": "p73 ลายมือ: <b>“squamous cell CA — base สกปรก · basal cell CA — ขอบมัน · basal cell CA nodular type — telangiectasia · malignant melanoma”</b>", "stem": "A 65-year-old woman has four photographed lesions: an ulcer with a dirty base, a pigmented nodule with a shiny border, a pink plaque with telangiectasia, and a pink nodule with a black component. Which one is malignant melanoma?", "opts": ["The pigmented nodule with a shiny border", "The pink nodule with a black component", "The pink plaque with telangiectasia", "None of them", "The ulcer with a dirty base"], "ans": 1, "interp": "", "why": "p73: A SCC (base สกปรก) · B BCC (ขอบมัน) · C BCC nodular (telangiectasia) · D malignant melanoma", "wrong": {"A": "= pigmented BCC", "C": "= nodular BCC", "D": "ไม่ใช่", "E": "= SCC"}, "summary": ["Spot: SCC base สกปรก · BCC ขอบมัน/telangiectasia · MM"], "kimg": ["l22_p73"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 73 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "img": ["l22_p73"]}, {"n": 105, "notes": "p2: <b>Subcutaneous fat</b> · p10 ลายมือ: <span class=\"hw\">ที่ชั้น subcu</span>", "stem": "A 40-year-old man has a 3-cm mobile mass deep to the dermis, within the fat layer, not attached to the skin. In which layer is the lesion located?", "opts": ["Reticular dermis", "Papillary dermis", "Subcutaneous tissue", "Epidermis", "Muscle fascia"], "ans": 2, "interp": "", "why": "p2: subcutaneous fat อยู่ใต้ reticular dermis · p10 ลายมือ lipoma ที่ชั้น subcu (ไม่ติด skin)", "wrong": {"A": "ยังเป็น dermis", "B": "ใต้ epidermis", "D": "บนสุด", "E": "ลึกกว่า"}, "summary": ["Lipoma = subcutaneous"], "kimg": ["l22_p2", "l22_p10", "l22_p11"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 2, 10, 11 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 106, "notes": "p4 ลายมือ: <b>skin tag → not required tx</b> · p6 ลายมือ: <b>Tx = จี้ออก (cosmetic)</b>", "stem": "A 65-year-old woman has two lesions: a soft pedunculated nodule on the neck and a brown, waxy, stuck-on plaque on the back. Which statement is correct?", "opts": ["Both are benign and may be removed for cosmetic reasons", "Both require radiotherapy", "The stuck-on plaque is a melanoma", "Both require wide excision with margins because they may become malignant", "The pedunculated nodule is premalignant"], "ans": 0, "interp": "", "why": "p4–6: skin tag (not required tx; เล็กตัด/จี้) · seborrheic keratosis (Tx = จี้ออก cosmetic) — ทั้งคู่ benign", "wrong": {"B": "ไม่ใช่", "C": "ไม่ใช่", "D": "ไม่จำเป็น", "E": "benign"}, "summary": ["Skin tag + SK = benign"], "kimg": ["l22_p4", "l22_p5", "l22_p6"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 4, 5, 6 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 107, "notes": "p15–16: <b>Complete excision sebaceous cyst</b> · p14 ลายมือ: <span class=\"hw\">ตัด punctum ออกด้วย</span>", "stem": "A 29-year-old woman has a 1.5-cm epidermal cyst on the cheek removed electively. The specimen shows an intact cyst with a small ellipse of skin containing the punctum. Why is this specimen ideal?", "opts": ["The cyst should have been ruptured to confirm the keratin content before removal", "Removing skin was unnecessary", "Only the contents needed removal", "Complete removal of the cyst wall with the punctum minimizes recurrence", "The punctum should be left to drain"], "ans": 3, "interp": "", "why": "p13–16: ติดผิวด้านบน ต้องเอา skin + punctum ออก · complete excision = ถุงไม่แตก ออกทั้งใบ → ไม่เป็นซ้ำ", "wrong": {"A": "ไม่ควร", "B": "จำเป็น", "C": "เหลือผนัง", "E": "เป็นซ้ำ"}, "summary": ["Complete excision ถุง + punctum"], "kimg": ["l22_p12", "l22_p13", "l22_p14", "l22_p15", "l22_p16"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 12, 13, 14, 15, 16 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 108, "notes": "p17 ลายมือ: <b>Haemangiomas = เป็นตั้งแต่เกิด / neonatal → โตเร็วมากในขวบปีแรก → หลังจากนั้นจะค่อย ๆ ฝ่อ · Vascular malformation = ค่อย ๆ โตตามตัว (ไม่มีช่วงโตเร็ว) → ไม่หายเอง</b>", "stem": "A 4-month-old boy has a lesion that appeared at 2 weeks of age and has grown much faster than the child. Which feature distinguishes it from a vascular malformation?", "opts": ["Presence at birth, with no growth at all afterwards", "Growth in proportion to the body", "A phase of rapid proliferation followed by involution", "Purple color in adulthood", "Never involuting"], "ans": 2, "interp": "", "why": "p17–19: hemangioma — rapid proliferation ขวบปีแรก → 90% involute · VM — โตตามตัว ไม่ยุบ", "wrong": {"A": "ไม่ใช่", "B": "= VM", "D": "= VM ผู้ใหญ่", "E": "= VM"}, "summary": ["Hemangioma โต-ยุบ · VM โตตามตัว"], "kimg": ["l22_p17", "l22_p18", "l22_p19"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 17, 18, 19 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 109, "notes": "p18: <b>Treatment : Observe +/- medication or surgery</b> · <b>90% involute over time</b>", "stem": "A 5-month-old girl has a 2-cm hemangioma on the trunk that is not ulcerated and does not affect function. What is the recommended management?", "opts": ["Embolization", "Immediate wide excision of the lesion with primary closure", "Observation because most hemangiomas involute", "Radiotherapy", "Interferon therapy"], "ans": 2, "interp": "", "why": "p18: treatment observe +/- medication or surgery · ลายมือ รักษาเมื่ออยู่ตำแหน่งสำคัญ (ตา หู airway) · ลำตัวเล็กไม่มีปัญหา → observe", "wrong": {"A": "= AVM", "B": "ไม่จำเป็น", "D": "ไม่ใช่", "E": "เลิกใช้"}, "summary": ["IH ทั่วไป → observe"], "kimg": ["l22_p17", "l22_p18"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 17, 18 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 110, "notes": "p19 ลายมือ: <b>คลำได้ pulse / thrills / bruit → arterial malformation</b> · p19: <b>Never involute</b>", "stem": "A 35-year-old woman has a vascular lesion of the hand present since childhood, enlarging with puberty and pregnancy, with a palpable thrill. Which statement is correct?", "opts": ["It is an infantile hemangioma that will involute after pregnancy", "It is a lymphatic malformation", "It will regress after delivery", "It is a low-flow capillary malformation", "It is a high-flow vascular malformation that will not involute"], "ans": 4, "interp": "", "why": "p19: VM never involute · high flow (pulse/thrills/bruit → arterial malformation)", "wrong": {"A": "ไม่ยุบ", "B": "สีผิว ไม่มี thrill", "C": "ไม่ยุบ", "D": "มี thrill = high flow"}, "summary": ["Thrill + ตั้งแต่เด็ก = high-flow VM"], "kimg": ["l22_p17", "l22_p19"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 17, 19 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 111, "notes": "p21 ลายมือ: <b>Bowen — เสี่ยง squamous cell carcinoma</b> · p23 ลายมือ: <b>Actinic keratosis — เสี่ยง squamous cell CA</b>", "stem": "A 65-year-old man has two lesions: a rough sun-damaged patch on the forehead and a well-demarcated red scaly plaque on the leg that is SCC in situ. Which statement is correct?", "opts": ["Both carry a risk of progression to squamous cell carcinoma", "Both are benign", "Only the sun-damaged forehead lesion is premalignant; the leg plaque is benign", "Both progress to melanoma", "Both progress to basal cell carcinoma"], "ans": 0, "interp": "", "why": "p21–23: Bowen's disease → SCC · actinic keratosis → SCC", "wrong": {"B": "premalignant", "C": "ทั้งคู่", "D": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["Bowen + AK → SCC"], "kimg": ["l22_p21", "l22_p23"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 21, 23 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 112, "notes": "p24: <b>77% are BCC</b> · p26 ลายมือ: <b>ตีนผม – ริมฝีปากบน</b>", "stem": "A 68-year-old man has a skin cancer at the hairline of the forehead. Considering both frequency and location, which type is most likely?", "opts": ["Liposarcoma", "Malignant melanoma", "Marjolin's ulcer", "Squamous cell carcinoma", "Basal cell carcinoma"], "ans": 4, "interp": "", "why": "p24: BCC 77% (common สุด) · p26 ลายมือ: BCC ตีนผม–ริมฝีปากบน", "wrong": {"A": "ไม่ใช่", "B": "3%", "C": "แผลเรื้อรัง", "D": "ริมฝีปากล่าง/มือ"}, "summary": ["BCC พบบ่อยสุด + ตีนผม"], "kimg": ["l22_p24", "l22_p26", "l22_p38"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 24, 26, 38 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 113, "notes": "p33 ลายมือ: <b>Rodent ulcer (พื้นแผลสะอาด)</b> · p31: <b>roll edge</b>", "stem": "An 80-year-old man has a slowly growing ulcer on the nose with a clean base and a raised, shiny, rolled edge with telangiectasia. Which statement about prognosis is correct?", "opts": ["It is benign and needs no treatment", "It is locally invasive but rarely metastasizes", "It will regress spontaneously", "It metastasizes to regional lymph nodes in most cases", "It is a premalignant lesion only"], "ans": 1, "interp": "", "why": "p31–33: BCC rolled pearly edge, telangiectasia · rodent ulcer พื้นสะอาด · 📖 BCC กินเฉพาะที่ แทบไม่แพร่", "wrong": {"A": "เป็นมะเร็ง", "C": "ไม่ใช่", "D": "SCC มากกว่า", "E": "เป็นมะเร็งแล้ว"}, "summary": ["BCC: local destruction, rare metastasis"], "kimg": ["l22_p27", "l22_p31", "l22_p32", "l22_p33", "l22_p34"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 27, 31, 32, 33, 34 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 114, "notes": "p44 ลายมือ: <b>“ส่วนใหญ่เป็น squamous CA”</b>", "stem": "A 62-year-old woman has a fungating ulcer with everted edges developing in a long-standing burn scar on the leg. Which histology is most likely?", "opts": ["Neurofibroma", "Melanoma", "Squamous cell carcinoma", "Lipoma", "Basal cell carcinoma"], "ans": 2, "interp": "", "why": "p35: SCC everted edge necrotic base · p44 ลายมือ Marjolin ส่วนใหญ่เป็น squamous CA", "wrong": {"A": "ไม่ใช่", "B": "ไม่ใช่", "D": "ไม่ใช่", "E": "ไม่ใช่ส่วนใหญ่"}, "summary": ["Marjolin → SCC"], "kimg": ["l22_p35", "l22_p37", "l22_p41", "l22_p42", "l22_p44"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 35, 37, 41, 42, 44 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 115, "notes": "p47: <b>Wide resection is not always possible, esp. Head and neck or facial area</b>", "stem": "A 58-year-old man has a basal cell carcinoma on the nasal tip. Which consideration drives the choice of surgical technique?", "opts": ["Wide margins of 2 cm are always used on the face", "Facial tumors never need clear margins", "Margins on the face must always be larger than those on the trunk to ensure cure", "Facial tumors are treated only by radiotherapy", "Function and appearance limit wide resection, so margin-controlled surgery is preferred"], "ans": 4, "interp": "", "why": "p47: wide resection ไม่ได้เสมอ esp. head-neck/face (function/aesthetic) → Mohs · p56 ลายมือ ใกล้ organ สำคัญ", "wrong": {"A": "ไม่ใช่", "B": "ต้อง clear", "C": "ไม่ใช่", "D": "ไม่ใช่"}, "summary": ["Face → margin-controlled (Mohs)"], "kimg": ["l22_p47", "l22_p56", "l22_p57"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 47, 56, 57 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 116, "notes": "p49: <b>ABCD criteria</b> · p46 ลายมือ: <b>แตกเป็นแผล, สีไม่สม่ำเสมอ</b>", "stem": "A 46-year-old woman has an 9-mm pigmented lesion on the calf that has become asymmetric with irregular borders and multiple colors, and recently bled. What is the next step?", "opts": ["Excisional biopsy of the lesion", "Laser removal without histology", "Cryotherapy", "Reassurance", "Topical steroid"], "ans": 0, "interp": "", "why": "p46: melanoma แตกเป็นแผล สีไม่สม่ำเสมอ · p49 ABCD ครบ → bx (📘 excisional 1–3 mm เพื่อวัด Breslow) · นอกสไลด์: NCCN: excisional biopsy 1–3 mm for suspected melanoma", "wrong": {"B": "ไม่มีชิ้นเนื้อ", "C": "ไม่มีชิ้นเนื้อ", "D": "อันตราย", "E": "ไม่ใช่"}, "summary": ["ABCD + bleeding → excisional bx"], "kimg": ["l22_p46", "l22_p49", "l22_p50", "l22_p73"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 46, 49, 50, 73 · ไม่มีสัญลักษณ์คณะ · ลายมือ · นอกสไลด์"}, {"n": 117, "notes": "p55: <b>2-4 mm — 2.0</b>", "stem": "A 52-year-old man has a 3.2-mm thick melanoma on the back. Which clinical excision margin is recommended?", "opts": ["4 cm", "5 cm", "0.5 cm", "2 cm", "1 cm"], "ans": 3, "interp": "", "why": "p55: 2–4 mm → 2.0 cm · p54 surgery wide excision", "wrong": {"A": "เกิน", "B": "เกิน", "C": "= in situ", "E": "< 1 mm"}, "summary": ["2–4 mm → 2 cm"], "kimg": ["l22_p54", "l22_p55"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 54, 55 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 118, "notes": "p58: <b>Advantage — High cure rates · Decrease morbidity · Significant tissue conservation</b>", "stem": "A 73-year-old woman with basal cell carcinoma of the eyelid chooses Mohs surgery. Which statement best summarizes its advantages?", "opts": ["It always avoids reconstruction", "No histology is needed", "High cure rate with maximal preservation of normal tissue", "Fast and cheap with no specialist needed", "Lower cure rate than standard excision but a better cosmetic result"], "ans": 2, "interp": "", "why": "p58: advantage — high cure rates, decrease morbidity, significant tissue conservation", "wrong": {"A": "ไม่เสมอ", "B": "ต้องมี", "D": "= disadvantage ตรงข้าม", "E": "cure สูง"}, "summary": ["Mohs: cure สูง + เก็บเนื้อดี"], "kimg": ["l22_p56", "l22_p57", "l22_p58"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 56, 57, 58 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 119, "notes": "p59 ลายมือ: <b>“∴ พลิกตัวทุก 2 ชม.” · “best = prevent”</b>", "stem": "A 78-year-old woman is admitted with a hip fracture and cannot move in bed. What is the most important intervention to prevent a sacral pressure injury?", "opts": ["Daily topical antibiotic cream on the sacrum", "Applying a tight bandage over the sacrum", "Keeping her in the same position to avoid pain", "Restricting fluids", "Repositioning every 2 hours"], "ans": 4, "interp": "", "why": "ลายมือ p59: > 2× capillary pressure 2 ชม. → irreversible ∴ พลิกตัวทุก 2 ชม. · best = prevent", "wrong": {"A": "ไม่ป้องกัน", "B": "กดเพิ่ม", "C": "แย่ลง", "D": "ไม่ใช่"}, "summary": ["พลิกตัวทุก 2 ชม."], "kimg": ["l22_p59"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 59 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 120, "notes": "p59: <b>Sitting position: ischial tuberosities</b> · p60: <b>Stage IV — Involvement of bone or joint</b>", "stem": "A 33-year-old paraplegic man has an ulcer over the ischial tuberosity with full-thickness loss down to bone. Which statement is correct?", "opts": ["It is a venous ulcer", "It is a Marjolin's ulcer", "It is a stage I pressure injury caused by lying supine for long periods", "It is a stage II injury of the sacrum", "It is a stage IV pressure injury caused by prolonged sitting"], "ans": 4, "interp": "", "why": "p59: sitting → ischial tuberosities · p60: stage IV = involvement of bone or joint", "wrong": {"A": "ไม่ใช่", "B": "ไม่ใช่", "C": "ผิดทั้ง stage และท่า", "D": "ผิดตำแหน่ง"}, "summary": ["Ischial + bone = stage IV จากการนั่ง"], "kimg": ["l22_p59", "l22_p60"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 59, 60 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 121, "notes": "p65 ลายมือ: <b>abscess → I&amp;D</b>", "stem": "A 28-year-old man has a single tender, fluctuant nodule on the thigh that began as a small follicular pustule. What is the best treatment now?", "opts": ["Wide excision", "Incision and drainage", "Oral dicloxacillin alone", "Antiviral therapy", "No treatment"], "ans": 1, "interp": "", "why": "p62–66: folliculitis → furuncle (abscess) → I&D", "wrong": {"A": "เกิน", "C": "ไม่พอเมื่อเป็นฝี", "D": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["Abscess → I&D"], "kimg": ["l22_p62", "l22_p63", "l22_p64", "l22_p65", "l22_p66"], "tags": ["Plastic", "Surgical infection"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 62, 63, 64, 65, 66 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 122, "notes": "p67 ลายมือ: <b>“I&amp;D อาจไม่ครบทุก pockets → Debride skin เลย”</b> · p68: <b>มีหลายรูเปิด → ต้อง debride</b>", "stem": "A 52-year-old diabetic woman had a carbuncle on the back treated by a single small incision. It continues to drain from several other openings. What should be done?", "opts": ["Surgical debridement of the involved skin and all pockets", "Radiotherapy", "Apply a pressure dressing", "Oral antibiotics only", "Repeat the same small incision and add oral antibiotics"], "ans": 0, "interp": "", "why": "ลายมือ p67: carbuncle = หลาย pockets → I&D อาจไม่ครบทุก pocket → debride skin เลย · p68 มีหลายรูเปิด → ต้อง debride", "wrong": {"B": "ไม่ใช่", "C": "ไม่ใช่", "D": "ไม่พอ", "E": "ไม่พอ"}, "summary": ["Carbuncle ระบายไม่หมด → debride"], "kimg": ["l22_p67", "l22_p68", "l22_p69"], "tags": ["Plastic", "Surgical infection"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 67, 68, 69 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 123, "notes": "p69 ลายมือ: <b>“mixed organism : G+, G− &amp; anaerobe — ลามเร็ว”</b>", "stem": "A 45-year-old man has necrotizing fasciitis of the abdominal wall after surgery. Cultures grow several organisms. Which description of the microbiology fits?", "opts": ["No organisms", "Mycobacterium tuberculosis spreading from the lungs", "Fungus only", "Mixed gram-positive, gram-negative and anaerobic organisms", "A single virus"], "ans": 3, "interp": "", "why": "ลายมือ p69: mixed organism : G+, G− & anaerobe — ลามเร็ว", "wrong": {"A": "ไม่ใช่", "B": "ไม่ใช่", "C": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["NF type I = polymicrobial"], "kimg": ["l22_p61", "l22_p69"], "tags": ["Plastic", "Surgical infection"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 61, 69 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 124, "notes": "p70 ลายมือ: <b>D — keratocanthoma</b>", "stem": "A 66-year-old man has a rapidly growing, crater-like nodule with a central keratin plug on his forearm, photographed as benign lesion 'D'. What is the diagnosis?", "opts": ["Lipoma", "Keratoacanthoma", "Nevus sebaceous", "Seborrheic keratosis", "Neurofibroma"], "ans": 1, "interp": "", "why": "p70 D: keratoacanthoma · p7 ปล่องภูเขาไฟ keratin plug", "wrong": {"A": "ใต้ผิว", "C": "= B", "D": "= A", "E": "= C"}, "summary": ["KA = crater + keratin plug"], "kimg": ["l22_p7", "l22_p70"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 7, 70 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 125, "notes": "p72: <b>Increases risk of: Malignancies · Primary HTN · Learning disabilities · Seizures · Follow up: Annual vision exam · BP monitoring · Annual full physical examination · Tumor surveillance</b>", "stem": "A 30-year-old man has dozens of soft cutaneous nodules on the back, six café-au-lait spots and iris hamartomas on slit-lamp exam. Which complication should be monitored for in this condition?", "opts": ["Malignant tumors and hypertension", "Keloids", "Varicose veins", "Pressure injuries", "Basal cell carcinoma of the scalp"], "ans": 0, "interp": "", "why": "p71–72: NF1 — increased risk of malignancies, primary HTN, learning disabilities, seizures · follow up annual vision exam, BP monitoring, physical exam, tumor surveillance", "wrong": {"B": "ไม่ใช่", "C": "ไม่ใช่", "D": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["NF1: เฝ้าระวัง tumor + BP + ตา"], "kimg": ["l22_p70", "l22_p71", "l22_p72"], "tags": ["Plastic", "Pediatric surgery"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 70, 71, 72 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 126, "notes": "p45 ลายมือ: <b>basal cell (less aggressive) = ขอ margin 0.5 cm</b>", "stem": "A 70-year-old man has a 1-cm biopsy-proven low-risk basal cell carcinoma on the back. Which clinical margin is recommended by current NCCN guidance, compared with the 0.5 cm in the classic teaching?", "opts": ["About 3 cm", "About 2 cm", "No margin", "About 1 mm", "About 4 mm"], "ans": 4, "interp": "", "why": "p45 ลายมือ: BCC = ขอ margin 0.5 cm · 📘 NCCN BCC v1.2027 low-risk: standard excision 4-mm clinical margin (ใกล้เคียง 0.5 cm) · นอกสไลด์: NCCN BCC v1.2027", "wrong": {"A": "เกิน", "B": "เกิน", "C": "ผิด", "D": "น้อยไป"}, "summary": ["Low-risk BCC → 4 mm (≈ 0.5 cm)"], "kimg": ["l22_p43", "l22_p45", "l22_p73"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 43, 45, 73 · ไม่มีสัญลักษณ์คณะ · ลายมือ · นอกสไลด์", "trap": "หน่วย mm vs cm"}, {"n": 127, "notes": "p8 ลายมือ: <b>congenital จะเสี่ยง melanoma · สงสัย CA ถ้ามี cardinal symptoms</b> · p9: <b>Change in color · Itching</b>", "stem": "A 30-year-old woman has a mole present since birth on her thigh that has recently become darker and itchy. What is the best management?", "opts": ["Cauterize without histology", "Apply topical steroid for itching", "Reassure, because moles that are present from birth are always benign", "Biopsy, because a congenital nevus with changes carries melanoma risk", "Observe for 5 years"], "ans": 3, "interp": "", "why": "ลายมือ p8: congenital → เสี่ยง melanoma (CMN) · สงสัย CA ถ้ามี cardinal symptoms · p9 change in color, itching → ควร bx", "wrong": {"A": "ไม่มีผลชิ้นเนื้อ", "B": "ไม่ใช่", "C": "ผิด", "E": "ช้า"}, "summary": ["CMN + เปลี่ยนแปลง → bx"], "kimg": ["l22_p8", "l22_p9"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 8, 9 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 128, "notes": "p22 ลายมือ: <b>“เสี่ยง basal cell carcinoma”</b>", "stem": "A 30-year-old man had a nevus sebaceous of the scalp since birth. Now a new firm nodule has appeared within it. Which tumor is classically feared?", "opts": ["Basal cell carcinoma", "Lipoma", "Melanoma", "Squamous cell carcinoma of the lip", "Keratoacanthoma"], "ans": 0, "interp": "", "why": "ลายมือ p22: nevus sebaceous → เสี่ยง basal cell carcinoma", "wrong": {"B": "ไม่ใช่", "C": "ไม่ใช่", "D": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["Nevus sebaceous → BCC"], "kimg": ["l22_p22", "l22_p26", "l22_p38", "l22_p70"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 22, 26, 38, 70 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 129, "notes": "p25: <b>Chronic inflammation</b> <span class=\"hw\">wear &amp; tear</span>", "stem": "A 50-year-old man has a chronic, nonhealing wound from a childhood injury that has been irritated for decades. Which risk factor for skin cancer does this represent?", "opts": ["UVA exposure", "Arsenic exposure", "Chronic inflammation", "Genetic predisposition", "Xeroderma pigmentosum"], "ans": 2, "interp": "", "why": "ลายมือ p25: chronic inflammation — wear & tear · p44 Marjolin: skin cancer on chronic ulcer", "wrong": {"A": "ไม่ใช่", "B": "ไม่ใช่", "D": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["แผลเรื้อรัง = chronic inflammation"], "kimg": ["l22_p25", "l22_p44"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 25, 44 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 130, "notes": "p23 ลายมือ: <b>“= m/c premalignant lesion · cf. seborrheic keratosis → benign”</b>", "stem": "A 72-year-old woman asks whether the scaly 'age spots' on her face are dangerous. One is stuck-on and greasy; another is rough and red on a sun-exposed area. Which lesion should be treated as premalignant?", "opts": ["The stuck-on greasy lesion", "The rough red lesion on sun-exposed skin", "Neither", "Both equally", "Only lesions larger than 5 cm"], "ans": 1, "interp": "", "why": "p6 SK benign · p23 AK = premalignant (เสี่ยง SCC) · cf. SK → benign", "wrong": {"A": "= SK", "C": "AK premalignant", "D": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["AK premalignant · SK benign"], "kimg": ["l22_p6", "l22_p23"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 6, 23 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 131, "notes": "p7 ลายมือ: <b>“ถ้าก้อนใหญ่ : อาจสับสนกับ squamous cell carcinoma (ลอง bx ไปตรวจ)”</b>", "stem": "A 69-year-old man has a 1-cm crater-shaped nodule with a keratin plug on the hand that grew within 4 weeks. A colleague says it will regress by itself and needs nothing. What is the best response?", "opts": ["Remove it for histology because it cannot be reliably separated from squamous cell carcinoma clinically", "Inject it with steroid only", "Agree and discharge without follow-up", "Refer for radiotherapy without biopsy, since these lesions are radiosensitive and often regress", "Treat it with oral antibiotics"], "ans": 0, "interp": "", "why": "ลายมือ p7: keratoacanthoma ถ้าก้อนใหญ่ อาจสับสนกับ SCC → ลอง bx ไปตรวจ (📖 แม้บางก้อนยุบเองได้ แต่แยก SCC ทางคลินิกไม่ได้ → excision)", "wrong": {"B": "ไม่มีชิ้นเนื้อ", "C": "เสี่ยงพลาด SCC", "D": "ไม่มี dx", "E": "ไม่ใช่การติดเชื้อ"}, "summary": ["KA → เอาออกส่งตรวจ"], "kimg": ["l22_p7"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 7 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "trap": "KA ยุบเองได้ จึงคิดว่าไม่ต้องทำอะไร"}, {"n": 132, "notes": "p9: <b>Change in size, shape, or thickness</b>", "stem": "A 38-year-old woman has a mole on her back that has become thicker and changed shape over 4 months, without itching or bleeding. What is the appropriate step?", "opts": ["Remove it by laser without histology, since it has not bled or itched", "Reassure because it is not itchy", "Apply a bleaching cream", "Biopsy, because change in size, shape or thickness is a cardinal sign", "Wait until it bleeds before acting"], "ans": 3, "interp": "", "why": "p9: cardinal signs — change in size, shape, or thickness (ข้อเดียวก็พอ) · itching · bleeding/ulceration → bx", "wrong": {"A": "ไม่มีผลชิ้นเนื้อ", "B": "ข้อเดียวพอ", "C": "ไม่ใช่", "E": "ช้า"}, "summary": ["Cardinal sign ข้อเดียวก็ bx"], "kimg": ["l22_p9"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 9 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์", "trap": "คิดว่าต้องมีอาการคันหรือเลือดออกด้วย"}, {"n": 133, "notes": "p12 ลายมือ: <b>ก้อนติดผิว (ติดรูขุมขน) ไม่ติดข้างล่าง</b> · p10 ลายมือ: <b>ก้อนโยกไปมาได้ (ไม่ติดกับ skin)</b>", "stem": "A 34-year-old man has a 2-cm smooth subcutaneous nodule on his back. Which finding best distinguishes an epidermal cyst from a lipoma?", "opts": ["Slow growth", "Soft consistency", "Lobulated outline", "Attachment to the overlying skin with a central punctum", "Free mobility under the skin without any skin attachment"], "ans": 3, "interp": "", "why": "p10/p12 ลายมือ: lipoma โยกได้ไม่ติด skin · sebaceous cyst ติดผิว (ติดรูขุมขน) มี punctum", "wrong": {"A": "ทั้งคู่", "B": "= lipoma", "C": "= lipoma", "E": "= lipoma"}, "summary": ["ติดผิว + punctum = cyst"], "kimg": ["l22_p10", "l22_p11", "l22_p12", "l22_p13"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 10, 11, 12, 13 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 134, "notes": "p19 ลายมือ: <b>“adult → hemang ควรฝ่อแล้ว ∴ น่าจะเป็น malform”</b>", "stem": "A 60-year-old woman has a soft purple lesion of the lower lip present since childhood. A student calls it a hemangioma. Why is this diagnosis unlikely?", "opts": ["Hemangiomas are always malignant", "Infantile hemangiomas should have involuted long before adulthood, so this is a venous malformation", "Hemangiomas appear only after age 40", "Hemangiomas never occur on the lip, so this must be a malignant vascular tumor instead", "Hemangiomas are always blue"], "ans": 1, "interp": "", "why": "ลายมือ p19: ปากเหี่ยวแล้ว = adult → hemang ควรฝ่อแล้ว ∴ น่าจะเป็น malform · สีม่วงน้ำเงิน = venous malformation", "wrong": {"A": "benign", "C": "เกิดในทารก", "D": "เกิดได้", "E": "สีแดง"}, "summary": ["ผู้ใหญ่ → VM ไม่ใช่ hemangioma"], "kimg": ["l22_p17", "l22_p19"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 17, 19 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "trap": "เรียกทุกก้อนเส้นเลือดว่า hemangioma"}, {"n": 135, "notes": "p20 ลายมือ: <b>“Tx = excision (not wide excision)”</b>", "stem": "A 58-year-old man has a 1.2-cm actinic keratosis on the back of the hand, and excision is planned. A resident proposes a 1-cm margin as for squamous cell carcinoma. What is the best response?", "opts": ["Add lymph node dissection", "Use a 2-cm margin to be safe", "A premalignant lesion needs excision of the lesion only, not a wide margin", "Use Mohs surgery routinely", "Agree, because all keratoses need the same 1-cm margin as invasive squamous cell carcinoma"], "ans": 2, "interp": "", "why": "ลายมือ p20: premalignant → excision (not wide excision) ไม่ต้องเอาเนื้อดีออกเยอะ · margin 1 cm ใช้กับ SCC (p45)", "wrong": {"A": "ไม่ใช่", "B": "เกิน", "D": "ไม่จำเป็น", "E": "= SCC"}, "summary": ["Premalignant ≠ wide excision"], "kimg": ["l22_p20"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 20 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "trap": "ใช้ margin ของมะเร็งกับ premalignant"}, {"n": 136, "notes": "p23 ลายมือ: <b>= m/c premalignant lesion · เสี่ยง squamous cell CA</b>", "stem": "A 70-year-old outdoor worker has many rough, sandpaper-like red papules on the bald scalp. Which mechanism and risk fit this lesion?", "opts": ["Pressure, with risk of ulceration", "Arsenic exposure, with risk of melanoma", "Cumulative sun damage, with risk of squamous cell carcinoma", "Viral infection, with no malignant risk", "Congenital hamartoma present since birth, with risk of basal cell carcinoma"], "ans": 2, "interp": "", "why": "p23 ลายมือ: actinic keratosis = m/c premalignant → SCC · ปื้นแดง/patch ที่ถูกแดด (p25 UVB)", "wrong": {"A": "ไม่ใช่", "B": "ไม่ใช่", "D": "ไม่ใช่", "E": "= nevus sebaceous"}, "summary": ["AK = sun damage → SCC"], "kimg": ["l22_p23"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 23 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 137, "notes": "p38 ลายมือ: <b>“upper lip → BCC มากกว่า ∵ เจอแดด · lower lips → SCC มากกว่า ∵ เจอ irritation”</b>", "stem": "A 74-year-old man has two facial tumors: one on the upper lip and one on the lower lip. Which explanation for their likely histology is correct?", "opts": ["The lower lip favors basal cell carcinoma because it is shaded, whereas the upper lip favors squamous cell carcinoma from sun exposure", "The upper lip is more sun-exposed and favors basal cell carcinoma; the lower lip is more irritated and favors squamous cell carcinoma", "Lip tumors are always benign", "The upper lip favors squamous cell carcinoma because of smoking", "Both lips favor melanoma"], "ans": 1, "interp": "", "why": "ลายมือ p26/p38: BCC ตีนผม–ริมฝีปากบน (เจอแดด) · ริมฝีปากล่าง → SCC (irritation บุหรี่ หมาก)", "wrong": {"A": "สลับ", "C": "ไม่ใช่", "D": "สลับ", "E": "ไม่ใช่"}, "summary": ["บน BCC (แดด) · ล่าง SCC (irritation)"], "kimg": ["l22_p26", "l22_p38"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 26, 38 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 138, "notes": "p27 ลายมือ: <b>“biopsy ขอบ ให้ติดเนื้อดีด้วย”</b> · p73 ลายมือ: <b>“ทำ incisional biopsy ส่งก่อน”</b>", "stem": "A 77-year-old woman has a 4-cm ulcerated tumor on the scalp suspected to be squamous cell carcinoma. A shave of the ulcer surface is planned. What is the best advice?", "opts": ["A surface shave taken from the ulcer center is sufficient for diagnosis", "Proceed to wide excision without biopsy", "Take an incisional biopsy from the edge including normal skin", "Take a fine-needle aspirate from the center", "Swab the ulcer for culture only"], "ans": 2, "interp": "", "why": "ลายมือ p27: bx ขอบให้ติดเนื้อดี → ดู transition · p73: สงสัย skin CA → incisional bx ส่งก่อน", "wrong": {"A": "ได้แต่ necrosis", "B": "ไม่มี dx", "D": "ไม่เหมาะ", "E": "ไม่ใช่"}, "summary": ["Incisional bx ที่ขอบ"], "kimg": ["l22_p27", "l22_p73"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 27, 73 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "trap": "ตัดกลางแผลแล้วได้แต่เนื้อตาย"}, {"n": 139, "notes": "p33 ลายมือ: <b>“Rodent ulcer → แผลแตกเป็น ulcer (พื้นแผลสะอาด)”</b>", "stem": "A 79-year-old man has a long-standing facial ulcer. Which pair of features suggests a rodent ulcer rather than squamous cell carcinoma?", "opts": ["Location on the lower lip", "Origin in an old burn scar", "Rapid growth with early nodal spread", "A dirty necrotic base with everted edges", "A clean base with a rolled, shiny edge"], "ans": 4, "interp": "", "why": "p33 ลายมือ: rodent ulcer พื้นแผลสะอาด (BCC ขอบมัน roll edge) · p35 SCC everted edge necrotic base", "wrong": {"A": "= SCC", "B": "= Marjolin (SCC)", "C": "= SCC", "D": "= SCC"}, "summary": ["Rodent ulcer: พื้นสะอาด ขอบม้วน"], "kimg": ["l22_p33", "l22_p34", "l22_p35", "l22_p37", "l22_p41", "l22_p42"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 33, 34, 35, 37, 41, 42 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 140, "notes": "p36 ลายมือ: <b>↓ poor prognosis</b>", "stem": "A 71-year-old man has cutaneous squamous cell carcinoma. The pathology report describes poor differentiation. How does this affect management and counseling?", "opts": ["It means the tumor is a basal cell carcinoma", "It has no prognostic meaning", "It allows a narrower margin because poorly differentiated tumors grow slowly and rarely spread to nodes", "It indicates a benign course", "It indicates a higher-risk tumor with a worse prognosis, needing closer attention to margins and follow-up"], "ans": 4, "interp": "", "why": "p36: well → moderate → poor differentiated (ลายมือ ↓ poor prognosis)", "wrong": {"A": "ไม่ใช่", "B": "มีความหมาย", "C": "ตรงข้าม", "D": "ไม่ใช่"}, "summary": ["Poor diff = high risk"], "kimg": ["l22_p35", "l22_p36", "l22_p37", "l22_p41", "l22_p42"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 35, 36, 37, 41, 42 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 141, "notes": "p38 ลายมือ: <b>“∵ เจอ irritation e.g. บุหรี่, หมาก”</b>", "stem": "A 64-year-old woman chews betel and also smokes. She has a chronic ulcer on the lower lip. Which statement is correct?", "opts": ["These habits matter only for melanoma", "Betel chewing protects the lip from cancer", "Smoking predisposes only to basal cell carcinoma of the upper lip, while betel chewing is protective for the lower lip", "Irritation is not a risk factor for skin cancer", "Both habits cause chronic irritation that predisposes the lower lip to squamous cell carcinoma"], "ans": 4, "interp": "", "why": "ลายมือ p38: lower lips → SCC ∵ irritation e.g. บุหรี่ หมาก · p25 chemical/chronic irritation", "wrong": {"A": "ไม่ใช่", "B": "ผิด", "C": "ไม่ใช่", "D": "ผิด"}, "summary": ["บุหรี่ + หมาก → SCC ริมฝีปากล่าง"], "kimg": ["l22_p25", "l22_p38", "l22_p39", "l22_p40"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 25, 38, 39, 40 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 142, "notes": "p44 ลายมือ: <b>“ต้อง bx → tx by wide excision”</b>", "stem": "A 56-year-old man has biopsy-proven squamous cell carcinoma arising in a chronic burn scar ulcer of the thigh. What is the definitive treatment?", "opts": ["Skin graft over the ulcer without excision", "Observation", "Dressings until healed", "Topical 5-fluorouracil", "Wide excision"], "ans": 4, "interp": "", "why": "p44 ลายมือ: Marjolin → ต้อง bx → tx by wide excision", "wrong": {"A": "เหลือมะเร็ง", "B": "ไม่ใช่", "C": "ไม่หาย", "D": "ไม่พอ"}, "summary": ["Marjolin → wide excision"], "kimg": ["l22_p43", "l22_p44", "l22_p45"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 43, 44, 45 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 143, "notes": "p49: <b>Diameter greater than 6 mm</b>", "stem": "A 37-year-old man has a 7-mm mole that is symmetric with a smooth border and a single uniform color. A friend says it is suspicious only if it exceeds 1 cm. Which statement is correct?", "opts": ["It meets no criteria because the diameter cutoff is 10 mm", "Diameter is not part of the criteria", "It meets the asymmetry criterion", "It meets only the diameter criterion, since the cutoff is 6 mm", "It meets all ABCD criteria"], "ans": 3, "interp": "", "why": "p49–50: D = diameter greater than 6 mm (ใหญ่กว่ายางลบดินสอ) · symmetric border เรียบ สีเดียว = ไม่เข้า A B C", "wrong": {"A": "cutoff 6 mm", "B": "มี D", "C": "symmetric", "E": "ไม่ครบ"}, "summary": ["D > 6 mm (ไม่ใช่ 10 mm)"], "kimg": ["l22_p49", "l22_p50"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 49, 50 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์", "trap": "cutoff เส้นผ่านศูนย์กลาง 6 mm ไม่ใช่ 1 cm"}, {"n": 144, "notes": "p55: <b>Thickness (mm) → Margin (cm)</b> · ลายมือ: <span class=\"hw\">Breslow's = บอก ค.ลึกเป็น mm · Clark's = บอกว่าอยู่ layer ไหน</span>", "stem": "A 49-year-old woman's melanoma report states 'Clark level IV, Breslow 1.8 mm'. Which value determines the recommended excision margin?", "opts": ["The patient's age", "The Clark level of invasion", "The lesion diameter", "The color of the lesion", "The Breslow thickness in millimeters"], "ans": 4, "interp": "", "why": "p48/p52 ลายมือ: Breslow = mm · Clark = layer · p55 ตาราง margin ใช้ thickness (mm) → 1–2 mm = 1–2 cm", "wrong": {"A": "ไม่ใช่", "B": "= layer ไม่ใช้ในตาราง", "C": "ไม่ใช่", "D": "ไม่ใช่"}, "summary": ["Margin ตาม Breslow (mm)"], "kimg": ["l22_p48", "l22_p52", "l22_p55"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 48, 52, 55 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "trap": "สับสน Clark level กับ Breslow"}, {"n": 145, "notes": "p55: <b>In situ — 0.5</b>", "stem": "A 44-year-old woman has melanoma in situ on the back. Which clinical excision margin is recommended for this lesion?", "opts": ["1 cm", "2 cm", "0.5 cm", "3 cm", "No margin"], "ans": 2, "interp": "", "why": "p55: in situ → 0.5 cm", "wrong": {"A": "< 1 mm", "B": "2–4 mm", "D": "> 4 mm", "E": "ไม่ใช่"}, "summary": ["In situ → 0.5 cm"], "kimg": ["l22_p55"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 55 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 146, "notes": "p57 ลายมือ: <b>“ตัดเพิ่มแค่ฝั่งที่ยัง positive จนกว่าจะ free → reconstruct + ปิดแผล”</b>", "stem": "A 69-year-old man has a basal cell carcinoma with ill-defined borders on the nose. During surgery, frozen sections show tumor at only the left margin. What happens next in Mohs surgery?", "opts": ["The wound is closed as it is and postoperative radiotherapy is given to the remaining tumor", "The surgery is abandoned", "A further 2-cm margin is taken all around the original defect", "Only the left side is excised further until margins are clear, then the defect is reconstructed", "The whole nose is removed"], "ans": 3, "interp": "", "why": "ลายมือ p57: เอาไปทำ frozen → ถ้า margin ไม่ free → ตัดต่อ · ตัดเพิ่มแค่ฝั่งที่ยัง positive จนกว่าจะ free → reconstruct + ปิดแผล", "wrong": {"A": "ยัง positive", "B": "ไม่ใช่", "C": "เกิน", "E": "เกิน"}, "summary": ["Mohs: ตัดเพิ่มเฉพาะฝั่ง positive"], "kimg": ["l22_p47", "l22_p56", "l22_p57"], "tags": ["Plastic", "Onco"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 47, 56, 57 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}, {"n": 147, "notes": "p59: <b>Treatment: relief of pressure, wound care, systemic enhancement</b>", "stem": "A 83-year-old bedbound man has a stage III sacral pressure injury. Nurses apply excellent dressings but he still lies on his back all day. Why is the wound not healing?", "opts": ["He needs systemic steroids", "Pressure injuries never heal", "Pressure has not been relieved, which is the first principle of treatment", "He needs immediate amputation", "The dressing type is wrong and should be changed to a silver dressing every day"], "ans": 2, "interp": "", "why": "p59: treatment — relief of pressure, wound care, systemic enhancement (ลายมือ พลิกตัวทุก 2 ชม.)", "wrong": {"A": "แย่ลง", "B": "หายได้", "D": "ไม่ใช่", "E": "ไม่ใช่หลัก"}, "summary": ["ต้อง off-load ก่อน"], "kimg": ["l22_p59"], "tags": ["Plastic"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 59 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์", "trap": "แผลดีแต่ไม่ off-load"}, {"n": 148, "notes": "p61: <b>Viral infections — Human papilloma virus · Pox virus · Herpes</b>", "stem": "A 12-year-old boy has rough, skin-colored papules on his fingers. Which organism most likely causes these lesions?", "opts": ["Staphylococcus aureus", "Human papillomavirus", "Gram-negative anaerobes", "Streptococcus pyogenes", "Pox virus causing furuncles"], "ans": 1, "interp": "", "why": "p61: viral infections — HPV (หูด), pox virus, herpes · bacterial — S. aureus, Strep pyogenes", "wrong": {"A": "bacteria", "C": "ไม่ใช่", "D": "bacteria", "E": "pox = molluscum ไม่ใช่ furuncle"}, "summary": ["หูด = HPV"], "kimg": ["l22_p61"], "tags": ["Plastic", "Surgical infection"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 61 · ไม่มีสัญลักษณ์คณะ · ตัวพิมพ์"}, {"n": 149, "notes": "p65 ลายมือ: <b>abscess → I&amp;D</b>", "stem": "A 26-year-old man has a 3-cm fluctuant abscess around a hair follicle on the buttock. A doctor prescribes oral dicloxacillin only. What is missing?", "opts": ["Wide excision of the involved buttock skin", "Radiotherapy", "Topical steroid", "Incision and drainage of the abscess", "Antiviral therapy"], "ans": 3, "interp": "", "why": "ลายมือ p62/p65: folliculitis หลายเม็ด → dicloxacillin · furuncle = abscess → I&D", "wrong": {"A": "เกิน", "B": "ไม่ใช่", "C": "ไม่ใช่", "E": "ไม่ใช่"}, "summary": ["Abscess ต้อง I&D"], "kimg": ["l22_p62", "l22_p63", "l22_p64", "l22_p65", "l22_p66"], "tags": ["Plastic", "Surgical infection"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 62, 63, 64, 65, 66 · ไม่มีสัญลักษณ์คณะ · ลายมือ", "trap": "ให้ยาอย่างเดียวกับฝี"}, {"n": 150, "notes": "p69 ลายมือ: <b>“dressing จนเกิด granulation tissue → แปะ graft”</b>", "stem": "A 61-year-old diabetic woman has necrotizing fasciitis of the thigh. After radical debridement and removal of the dead overlying skin, how is the wound managed?", "opts": ["Antibiotics alone without further surgery until the wound closes", "Amputation in every case", "Serial dressings until granulation tissue forms, then skin grafting", "Leave the dead skin in place", "Immediate primary closure"], "ans": 2, "interp": "", "why": "ลายมือ p69: Tx : debride → เอา skin ข้างบนทิ้งหมด → dressing จนเกิด granulation tissue → แปะ graft", "wrong": {"A": "ไม่พอ", "B": "ไม่ทุกราย", "D": "ผิด", "E": "ติดเชื้อซ้ำ"}, "summary": ["NF: debride → dressing → granulation → graft"], "kimg": ["l22_p2", "l22_p69"], "tags": ["Plastic", "Surgical infection"], "src": "L22 Skin and Subcutaneous Tissue · หน้า 2, 69 · ไม่มีสัญลักษณ์คณะ · ลายมือ"}]});
